{"command": "cd /testbed && mkdir -p test/cjs/payments/p2sh && cat > test/cjs/payments/p2sh/p2sh.test.js <<'EOF'
'use strict';

const { p2sh } = require('../../../../src/cjs/payments/p2sh.cjs');
const bscript = require('../../../../src/cjs/script.cjs');
const networks = require('../../../../src/cjs/networks.cjs');
const tools = require('uint8array-tools');
const fixture = require('../../../fixtures/p2sh.json');

const OPS = bscript.OPS;

// ---------------------------------------------------------------------------
// Helpers that translate the JSON fixtures (which use hex/ASM strings and
// network names) into the Uint8Array/network-object form consumed by p2sh().
// ---------------------------------------------------------------------------

const asmToBuffer = asm => {
  if (typeof asm !== 'string') return asm;
  // bscript.fromASM rejects the empty string, although an empty script is a
  // perfectly valid input for p2sh.
  if (asm === '') return new Uint8Array(0);
  return bscript.fromASM(asm);
};

const toNetwork = network =>
  typeof network === 'string' ? networks[network] : network;

const convertRedeem = redeem => {
  const result = {};
  for (const [key, value] of Object.entries(redeem)) {
    switch (key) {
      case 'network':
        result.network = toNetwork(value);
        break;
      case 'output':
      case 'input':
        result[key] = asmToBuffer(value);
        break;
      case 'witness':
        result.witness = value.map(tools.fromHex);
        break;
      default:
        // Unknown context fields (address/pubkey/hash/name/...) are ignored
        // by p2sh and are intentionally left untouched.
        result[key] = value;
    }
  }
  return result;
};

const convertArguments = args => {
  const result = {};
  for (const [key, value] of Object.entries(args)) {
    switch (key) {
      case 'network':
        result.network = toNetwork(value);
        break;
      case 'hash':
        result.hash = tools.fromHex(value);
        break;
      case 'output':
      case 'input':
        result[key] = asmToBuffer(value);
        break;
      case 'outputHex':
        result.output = tools.fromHex(value);
        break;
      case 'inputHex':
        result.input = tools.fromHex(value);
        break;
      case 'witness':
        result.witness = value.map(tools.fromHex);
        break;
      case 'redeem':
        result.redeem = convertRedeem(value);
        break;
      default:
        result[key] = value;
    }
  }
  return result;
};

const assertExpected = (payment, expected) => {
  if ('name' in expected) expect(payment.name).toBe(expected.name);
  if ('address' in expected) expect(payment.address).toBe(expected.address);
  if ('hash' in expected) expect(tools.toHex(payment.hash)).toBe(expected.hash);
  if ('output' in expected)
    expect(bscript.toASM(payment.output)).toBe(expected.output);
  if ('input' in expected)
    expect(bscript.toASM(payment.input)).toBe(expected.input);
  if ('network' in expected)
    expect(payment.network).toBe(toNetwork(expected.network));

  if ('witness' in expected) {
    if (expected.witness === null) {
      expect(payment.witness).toBeUndefined();
    } else {
      expect(payment.witness.map(tools.toHex)).toEqual(expected.witness);
    }
  }

  if ('redeem' in expected) {
    if (expected.redeem === null) {
      expect(payment.redeem).toBeUndefined();
    } else {
      expect(payment.redeem).toBeDefined();
      if ('output' in expected.redeem)
        expect(bscript.toASM(payment.redeem.output)).toBe(
          expected.redeem.output,
        );
      if ('input' in expected.redeem)
        expect(bscript.toASM(payment.redeem.input)).toBe(
          expected.redeem.input,
        );
      if ('witness' in expected.redeem)
        expect(payment.redeem.witness.map(tools.toHex)).toEqual(
          expected.redeem.witness,
        );
    }
  }
};

// ---------------------------------------------------------------------------
// Fixture-driven valid vectors
// ---------------------------------------------------------------------------

describe('p2sh (valid fixtures)', () => {
  const valid = fixture.valid.map((vector, index) => [index, vector]);

  test.each(valid)(
    'valid vector #%i: %s',
    (_index, vector) => {
      const args = convertArguments(vector.arguments);
      const payment = p2sh(args, vector.options);

      expect(payment).toBeDefined();
      expect(payment.network).toBeDefined();
      expect(typeof payment.name).toBe('string');
      expect(payment.name.startsWith('p2sh')).toBe(true);
      assertExpected(payment, vector.expected);
    },
  );
});

// ---------------------------------------------------------------------------
// Fixture-driven invalid vectors
// ---------------------------------------------------------------------------

describe('p2sh (invalid fixtures)', () => {
  const invalid = fixture.invalid.map((vector, index) => [index, vector]);

  test.each(invalid)(
    'invalid vector #%i throws (%s)',
    (_index, vector) => {
      const args = convertArguments(vector.arguments);
      const expected = vector.exception.replace(/^ValiError:\s*/, '');
      expect(() => p2sh(args, vector.options)).toThrow(expected);
    },
  );
});

// ---------------------------------------------------------------------------
// Targeted behavioural tests (beyond the fixtures)
// ---------------------------------------------------------------------------

describe('p2sh (behaviour)', () => {
  const hashHex = '9f840a5fc02407ef0ad499c2ec0eb0b942fb0086';
  const address = '3GETYP4cuSesh2zsPEEYVZqnRedwe4FwUT';

  test('throws a TypeError when no usable data is supplied', () => {
    expect(() => p2sh({})).toThrow(TypeError);
    expect(() => p2sh({})).toThrow('Not enough data');
  });

  test('defaults the network to bitcoin', () => {
    const payment = p2sh({ hash: tools.fromHex(hashHex) });
    expect(payment.network).toBe(networks.bitcoin);
    expect(payment.address).toBe(address);
  });

  test('derives hash/output/address from a supplied address', () => {
    const payment = p2sh({ address });
    expect(tools.toHex(payment.hash)).toBe(hashHex);
    expect(bscript.toASM(payment.output)).toBe(
      `OP_HASH160 ${hashHex} OP_EQUAL`,
    );
    expect(payment.address).toBe(address);
    expect(payment.redeem).toBeUndefined();
    expect(payment.input).toBeUndefined();
    expect(payment.witness).toBeUndefined();
  });

  test('derives hash/address/output from redeem.output', () => {
    const redeemOutput = bscript.fromASM(
      'OP_DUP OP_HASH160 c30afa58ae0673b00a45b5c17dff4633780f1400 OP_EQUALVERIFY OP_CHECKSIG',
    );
    const payment = p2sh({ redeem: { output: redeemOutput } });
    expect(tools.toHex(payment.hash)).toBe(hashHex);
    expect(payment.address).toBe(address);
    expect(bscript.toASM(payment.output)).toBe(
      `OP_HASH160 ${hashHex} OP_EQUAL`,
    );
  });

  test('uses testnet network from redeem and creates a testnet address', () => {
    const redeemOutput = bscript.fromASM(
      'OP_DUP OP_HASH160 c30afa58ae0673b00a45b5c17dff4633780f1400 OP_EQUALVERIFY OP_CHECKSIG',
    );
    const payment = p2sh({
      redeem: { output: redeemOutput, network: networks.testnet },
    });
    expect(payment.network).toBe(networks.testnet);
    expect(payment.address).toBe('2N7nfc7zeWuADtpdR4MrR7Wq3dzr7LxTCgS');
  });

  test('derives redeem input/output from a combined scriptSig', () => {
    const input = bscript.fromASM(
      '3045022100e4fce9ec72b609a2df1dc050c20dcf101d27faefb3e686b7a4cb067becdd5e8e022071287fced53806b08cf39b5ad58bbe614775b3776e98a9f8760af0d4d1d47a9501 2103e15819590382a9dd878f01e2f0cbce541564eb415e43b440472d883ecd283058ac',
    );
    const payment = p2sh({ input });

    expect(payment.redeem).toBeDefined();
    expect(bscript.toASM(payment.redeem.output)).toBe(
      '03e15819590382a9dd878f01e2f0cbce541564eb415e43b440472d883ecd283058 OP_CHECKSIG',
    );
    expect(bscript.toASM(payment.redeem.input)).toBe(
      '3045022100e4fce9ec72b609a2df1dc050c20dcf101d27faefb3e686b7a4cb067becdd5e8e022071287fced53806b08cf39b5ad58bbe614775b3776e98a9f8760af0d4d1d47a9501',
    );
    expect(payment.redeem.witness).toEqual([]);
    expect(payment.witness).toEqual([]);
    expect(payment.address).toBe('36TibC8RrPB9WrBdPoGXhHqDHJosyFVtVQ');
  });

  test('treats a trailing OP_FALSE in a scriptSig as an empty redeem output', () => {
    // scriptSig: OP_0 OP_FALSE => redeemScript is OP_FALSE (empty script).
    // p2sh maps OP_FALSE to an empty redeem.output to support P2WPKH.
    const input = bscript.fromASM(
      'OP_0 0014c30afa58ae0673b00a45b5c17dff4633780f1400 OP_FALSE',
    );
    const payment = p2sh({ input });
    expect(payment.redeem).toBeDefined();
    expect(payment.redeem.output).toEqual(new Uint8Array(0));
    expect(payment.address).toBeDefined();
  });

  test('propagates redeem.witness to witness', () => {
    const witness = [
      tools.fromHex(
        '3045022100e4fce9ec72b609a2df1dc050c20dcf101d27faefb3e686b7a4cb067becdd5e8e022071287fced53806b08cf39b5ad58bbe614775b3776e98a9f8760af0d4d1d47a9501',
      ),
      tools.fromHex(
        '03e15819590382a9dd878f01e2f0cbce541564eb415e43b440472d883ecd283058',
      ),
    ];
    const redeemOutput = bscript.fromASM(
      'OP_0 c30afa58ae0673b00a45b5c17dff4633780f1400',
    );
    const payment = p2sh({
      redeem: { output: redeemOutput, input: new Uint8Array(0), witness },
    });
    expect(payment.witness).toEqual(witness);
  });

  test('includes redeem.name in the payment name', () => {
    const payment = p2sh({
      redeem: { output: bscript.compile([OPS.OP_1]), name: 'p2pkh' },
    });
    expect(payment.name).toBe('p2sh-p2pkh');
  });

  test('does not validate when opts.validate is false', () => {
    // 23 bytes with an invalid opcode layout. With validation enabled this is
    // rejected; with validation disabled it is accepted verbatim.
    const badOutput = new Uint8Array(23).fill(OPS.OP_1);

    expect(() => p2sh({ output: badOutput })).toThrow('Output is invalid');
    const payment = p2sh({ output: badOutput }, { validate: false });

    expect(payment.output).toBe(badOutput);
    expect(tools.toHex(payment.hash)).toBe(
