import { p2sh } from '../../../../src/cjs/payments/p2sh.cjs';
import * as bscript from '../../../../src/cjs/script.cjs';
import * as networks from '../../../../src/cjs/networks.cjs';
import * as tools from 'uint8array-tools';
import fixture from '../../../fixtures/p2sh.json' with { type: 'json' };

const OPS = bscript.OPS;

// ---------------------------------------------------------------------------
// Helpers that translate the JSON fixtures (which use hex/ASM strings and
// network names) into the Uint8Array/network-object form consumed by p2sh().
// ---------------------------------------------------------------------------

const asmToBuffer = asm => {
  if (typeof asm !== 'string') return asm;
  // bscript.fromASM rejects the empty string, although an empty script is a
  // perfectly valid input for p2sh.
  if (asm === '') return new Uint8Array(0);
  return bscript.fromASM(asm);
};

const toNetwork = network =>
  typeof network === 'string' ? networks[network] : network;

const convertRedeem = redeem => {
  const result = {};
  for (const [key, value] of Object.entries(redeem)) {
    switch (key) {
      case 'network':
        result.network = toNetwork(value);
        break;
      case 'output':
      case 'input':
        result[key] = asmToBuffer(value);
        break;
      case 'witness':
        result.witness = value.map(tools.fromHex);
        break;
      default:
        // Unknown context fields (address/pubkey/hash/name/...) are ignored
        // by p2sh and are intentionally left untouched.
        result[key] = value;
    }
  }
  return result;
};

const convertArguments = args => {
  const result = {};
  for (const [key, value] of Object.entries(args)) {
    switch (key) {
      case 'network':
        result.network = toNetwork(value);
        break;
      case 'hash':
        result.hash = tools.fromHex(value);
        break;
      case 'output':
      case 'input':
        result[key] = asmToBuffer(value);
        break;
      case 'outputHex':
        result.output = tools.fromHex(value);
        break;
      case 'inputHex':
        result.input = tools.fromHex(value);
        break;
      case 'witness':
        result.witness = value.map(tools.fromHex);
        break;
      case 'redeem':
        result.redeem = convertRedeem(value);
        break;
      default:
        result[key] = value;
    }
  }
  return result;
};

const assertExpected = (payment, expected) => {
  const check = (actual, value, format) => {
    if (value === null) expect(actual).toBeUndefined();
    else expect(format(actual)).toBe(value);
  };

  if ('name' in expected) check(payment.name, expected.name, x => x);
  if ('address' in expected) check(payment.address, expected.address, x => x);
  if ('hash' in expected)
    check(payment.hash, expected.hash, tools.toHex);
  if ('output' in expected)
    check(payment.output, expected.output, bscript.toASM);
  if ('input' in expected)
    check(payment.input, expected.input, bscript.toASM);
  if ('network' in expected)
    expect(payment.network).toBe(toNetwork(expected.network));

  if ('witness' in expected) {
    if (expected.witness === null) {
      expect(payment.witness).toBeUndefined();
    } else {
      expect(payment.witness.map(tools.toHex)).toEqual(expected.witness);
    }
  }

  if ('redeem' in expected) {
    if (expected.redeem === null) {
      expect(payment.redeem).toBeUndefined();
    } else {
      expect(payment.redeem).toBeDefined();
      const checkPart = (actual, value) => {
        if (value === null) expect(actual).toBeUndefined();
        else expect(bscript.toASM(actual)).toBe(value);
      };
      if ('output' in expected.redeem)
        checkPart(payment.redeem.output, expected.redeem.output);
      if ('input' in expected.redeem)
        checkPart(payment.redeem.input, expected.redeem.input);
      if ('witness' in expected.redeem)
        expect(payment.redeem.witness.map(tools.toHex)).toEqual(
          expected.redeem.witness,
        );
    }
  }
};

