function taggedHash(tag, ...data) {
  const tagHash = crypto.createHash('sha256').update(tag, 'utf8').digest();
  const h = crypto.createHash('sha256');
  h.update(tagHash); h.update(tagHash);
  for (const d of data) h.update(Buffer.from(d));
  return new Uint8Array(h.digest());
}
function serializeScript(s) {
  // scripts here < 253 bytes
  if (s.length < 0xfd) return Uint8Array.from([s.length, ...s]);
