const leafA = hex('20d85a959b0290bf19bb89ed43c916be835475d013da4b362117393e25a48229b8ac');
const leafB = Uint8Array.from([0x51]); // OP_TRUE
const scriptTree = [ { output: leafA, version: 0xc0 }, { output: leafB, version: 0xc0 } ];
