const withAnnex = p2tr({ witness: [sig, annex] });
console.log('annex: sig', toHex(withAnnex.signature), 'hash', withAnnex.hash, 'witnesslen', withAnnex.witness.length);
const scriptAnnex = p2tr({ witness: [...full.witness, annex] });
