    });
    expect(toHex(p.redeem.output)).toBe(LEAF_A);
    expect(p.redeem.witness).toHaveLength(1);
    expect(toHex(p.redeem.witness[0])).toBe('010203');
    // the annex/control block is not part of the redeem stack
    expect(toHex(p.signature)).toBeUndefined();
  });

