  test('builds a key path witness from a bare signature', () => {
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      signature: fromHex(SIG64),
    });
    expect(p.witness).toHaveLength(1);
    expect(toHex(p.witness[0])).toBe(SIG64);
  });
});

describe('p2tr address validation', () => {
  test('rejects an address for another network', () => {
    expect(() => p2tr({ address: KEY_PATH_TESTNET })).toThrow(TypeError);
    expect(() => p2tr({ address: KEY_PATH_TESTNET })).toThrow(
      'Invalid prefix or Network mismatch',
    );
    expect(() =>
      p2tr({ address: KEY_PATH_MAINNET, network: testnet }),
    ).toThrow('Invalid prefix or Network mismatch');
  });

  test('rejects addresses with the wrong witness version', () => {
    // witness v0 (a p2wpkh address)
    const v0words = bech32.toWords(new Uint8Array(20).fill(2));
    v0words.unshift(0);
    const v0 = bech32.encode('bc', v0words);
    expect(() => p2tr({ address: v0 })).toThrow('Invalid address version');

    // witness v2
    const v2words = bech32m.toWords(new Uint8Array(32).fill(1));
    v2words.unshift(2);
    const v2 = bech32m.encode('bc', v2words);
    expect(() => p2tr({ address: v2 })).toThrow('Invalid address version');
  });

  test('rejects a witness v1 address with the wrong data length', () => {
    const words = bech32m.toWords(new Uint8Array(20).fill(1));
    words.unshift(1);
    const shortData = bech32m.encode('bc', words);
    expect(() => p2tr({ address: shortData })).toThrow(TypeError);
    expect(() => p2tr({ address: shortData })).toThrow('Invalid address data');
  });

  test('rejects malformed addresses', () => {
    expect(() => p2tr({ address: 'not-an-address' })).toThrow(
      /No separator character/,
    );
  });
});

describe('p2tr pubkey and output validation', () => {
  test('rejects a pubkey that does not match the address', () => {
    expect(() =>
      p2tr({ address: KEY_PATH_MAINNET, pubkey: fromHex(OTHER_KEY) }),
    ).toThrow('Pubkey mismatch');
  });

  test('rejects a pubkey that does not match the output', () => {
    expect(() =>
      p2tr({ output: fromHex(KEY_PATH_SPK), pubkey: fromHex(OTHER_KEY) }),
    ).toThrow('Pubkey mismatch');
  });

  test('accepts matching pubkey and output', () => {
    const p = p2tr({
      output: fromHex(KEY_PATH_SPK),
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
    });
    expect(p.address).toBe(KEY_PATH_MAINNET);
  });

  test('rejects malformed outputs', () => {
    // wrong length is caught by the argument schema
    expect(() => p2tr({ output: new Uint8Array(33) })).toThrow(
      /Expected 34 but received 33/,
    );
    // OP_0 instead of OP_1
    expect(() =>
      p2tr({ output: Uint8Array.from([0x00, 0x20, ...new Uint8Array(32)]) }),
    ).toThrow('Output is invalid');
    // wrong push length byte
    expect(() =>
      p2tr({ output: Uint8Array.from([0x51, 0x1f, ...new Uint8Array(32)]) }),
    ).toThrow('Output is invalid');
  });

  test('rejects a scriptPubKey whose key is not on the curve', () => {
    expect(() =>
      p2tr({ output: Uint8Array.from([0x51, 0x20, ...new Uint8Array(32)]) }),
    ).toThrow('Invalid pubkey for p2tr');
    expect(() => p2tr({ pubkey: new Uint8Array(32) })).toThrow(
      'Invalid pubkey for p2tr',
    );
  });
});

describe('p2tr hash and redeem validation', () => {
  test('rejects a merkle root that does not match the script tree', () => {
    expect(() =>
      keyPath({ scriptTree: tree1(), hash: new Uint8Array(32) }),
    ).toThrow('Hash mismatch');
  });

  test('accepts a merkle root that matches the script tree', () => {
    const p = keyPath({ scriptTree: tree1(), hash: fromHex(TREE1_ROOT) });
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
    expect(p.address).toBe(TREE1_ADDRESS);
  });

  test('rejects a redeem script that is not in the tree', () => {
    expect(() =>
      keyPath({ scriptTree: tree1(), redeem: { output: fromHex('53') } }),
    ).toThrow('Redeem script not in tree');
  });

  test('rejects an empty redeem script', () => {
    expect(() =>
      p2tr({
        witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        redeem: { output: new Uint8Array(0) },
      }),
    ).toThrow('Redeem.output is invalid');
  });

  test('rejects a redeem script that does not match the witness', () => {
    expect(() =>
      p2tr({
        witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        redeem: leaf(LEAF_B),
      }),
    ).toThrow('Redeem.output and witness mismatch');
  });

  test('rejects a redeem version that does not match the witness', () => {
    expect(() =>
      p2tr({
        witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        redeem: { output: fromHex(LEAF_A), redeemVersion: 0xc2 },
      }),
    ).toThrow('Redeem.redeemVersion and witness mismatch');
  });

  test('accepts a matching redeem version', () => {
    const p = p2tr({
