      }),
    ).toThrow('Redeem.witness and witness mismatch');
  });

  test('accepts a matching redeem stack', () => {
    const p = p2tr({
      witness: [fromHex('010203'), fromHex(LEAF_A), fromHex(TREE1_CB_A)],
      redeem: { witness: [fromHex('010203')] },
    });
    expect(p.redeem.witness).toHaveLength(1);
    expect(toHex(p.redeem.witness[0])).toBe('010203');
  });
});

describe('p2tr signature validation', () => {
  test('rejects a signature that does not match the witness', () => {
    expect(() =>
      p2tr({
        pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
        witness: [fromHex(SIG64)],
        signature: fromHex('09'.repeat(64)),
      }),
    ).toThrow('Signature mismatch');
  });

  test('accepts a matching signature', () => {
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      witness: [fromHex(SIG64)],
      signature: fromHex(SIG64),
    });
    expect(toHex(p.signature)).toBe(SIG64);
  });
});

describe('p2tr control block validation', () => {
  test('rejects a control block that is too short', () => {
    const shortCb = Uint8Array.from([0xc0, ...new Uint8Array(10)]);
    expect(() =>
      p2tr({ witness: [fromHex(LEAF_A), shortCb] }),
    ).toThrow(TypeError);
    expect(() => p2tr({ witness: [fromHex(LEAF_A), shortCb] })).toThrow(
      'The control-block length is too small. Got 11, expected min 33.',
    );
  });

  test('rejects a control block with a partial merkle path', () => {
    const cb = fromHex(`c0${INTERNAL_KEY}00`);
    expect(() => p2tr({ witness: [fromHex(LEAF_A), cb] })).toThrow(
      'The control-block length of 34 is incorrect!',
    );
  });

  test('rejects a merkle path that is too long', () => {
    const cb = new Uint8Array(33 + 32 * 129).fill(3);
    cb[0] = 0xc0;
    cb.set(fromHex(INTERNAL_KEY), 1);
    expect(() => p2tr({ witness: [fromHex(LEAF_A), cb] })).toThrow(
      'The script path is too long. Got 129, expected max 128.',
    );
  });

  test('accepts a maximum depth merkle path', () => {
    const cb = new Uint8Array(33 + 32 * 128).fill(3);
    cb[0] = 0xc0;
    cb.set(fromHex(INTERNAL_KEY), 1);
    const p = p2tr({ witness: [fromHex(LEAF_A), cb] });
    expect(toHex(p.internalPubkey)).toBe(INTERNAL_KEY);
    expect(p.address).toBe(
      'bc1plqydgkz4q5swfuksauy9vud5thsk8fq2n5fk2uls4869l5tdvgeqcvhpjw',
    );
  });

  test('rejects a control block with a different internal pubkey', () => {
    expect(() =>
      p2tr({
        witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        internalPubkey: fromHex(OTHER_KEY),
      }),
    ).toThrow('Internal pubkey mismatch');
  });

  test('rejects a control block with an invalid internal pubkey', () => {
    const cb = Uint8Array.from([0xc0, ...new Uint8Array(32)]);
    expect(() => p2tr({ witness: [fromHex(LEAF_A), cb] })).toThrow(
      'Invalid internalPubkey for p2tr witness',
    );
  });

  test('rejects a control block that commits to another output key', () => {
    expect(() =>
      p2tr({
        witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        pubkey: fromHex(OTHER_KEY),
      }),
    ).toThrow('Pubkey mismatch for p2tr witness');
  });

  test('rejects a control block with the wrong parity', () => {
    const flipped = fromHex(TREE1_CB_A);
    flipped[0] = flipped[0] ^ 1;
    let err;
    try {
      p2tr({ witness: [fromHex(LEAF_A), flipped] });
    } catch (e) {
      err = e;
    }
    expect(err).toBeInstanceOf(Error);
    expect(err).not.toBeInstanceOf(TypeError);
    expect(err.message).toBe('Incorrect parity');
  });

  test('accepts a witness with the same payment data attached', () => {
    const p = p2tr({
      witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
      internalPubkey: fromHex(INTERNAL_KEY),
      hash: fromHex(TREE1_ROOT),
      pubkey: fromHex(TREE1_OUTPUT_KEY),
      address: TREE1_ADDRESS,
    });
    expect(p.address).toBe(TREE1_ADDRESS);
    expect(toHex(p.output)).toBe(`5120${TREE1_OUTPUT_KEY}`);
  });
});

describe('p2tr without validation', () => {
  test('skips extended validation when validate is false', () => {
    // the testnet address would normally be rejected for the mainnet network
    const p = p2tr({ address: KEY_PATH_TESTNET }, { validate: false });
    expect(p.address).toBe(KEY_PATH_TESTNET);
    expect(toHex(p.pubkey)).toBe(KEY_PATH_OUTPUT_KEY);
    expect(toHex(p.output)).toBe(KEY_PATH_SPK);
    expect(p.network).toBe(bitcoin);
  });

  test('does not check the output script format when validate is false', () => {
    const bad = Uint8Array.from([0x00, 0x20, ...fromHex(KEY_PATH_OUTPUT_KEY)]);
    const p = p2tr({ output: bad }, { validate: false });
    expect(toHex(p.output)).toBe(toHex(bad));
    expect(toHex(p.pubkey)).toBe(KEY_PATH_OUTPUT_KEY);
    expect(p.address).toBe(KEY_PATH_MAINNET);
  });

  test('still rejects an invalid merkle root when validate is false', () => {
    // a provided hash is used as-is, so the resulting key is different
    const p = p2tr(
      { internalPubkey: fromHex(INTERNAL_KEY), hash: new Uint8Array(32) },
      { validate: false },
    );
    expect(toHex(p.hash)).toBe('00'.repeat(32));
    expect(p.address).not.toBe(KEY_PATH_MAINNET);
  });
});
