// key-path case, against the official BIP-341 wallet test vector:
//   internal key d6889c...a961d -> output key 53a1f6...a343
//                              -> bc1p2wsldez5mud2yam29q22wgfh9439spgduvct83k3pm50fcxa5dps59h4z5
// ---------------------------------------------------------------------------

// internal (untweaked) x-only key
const INTERNAL_KEY =
  'd6889cb081036e0faefa3a35157ad71086b123b2b144b649798b494c300a961d';
// another valid internal key (BIP-86 test vector key)
const OTHER_KEY =
  'cc8a4bc64d897bddc5fbc2f670f7a8ba0b386779106cf1223c6fc5d7cd6fc115';

// key-path only (no script tree) results
const KEY_PATH_OUTPUT_KEY =
  '53a1f6e454df1aa2776a2814a721372d6258050de330b3c6d10ee8f4e0dda343';
const KEY_PATH_SPK = `5120${KEY_PATH_OUTPUT_KEY}`;
const KEY_PATH_MAINNET =
  'bc1p2wsldez5mud2yam29q22wgfh9439spgduvct83k3pm50fcxa5dps59h4z5';
const KEY_PATH_TESTNET =
  'tb1p2wsldez5mud2yam29q22wgfh9439spgduvct83k3pm50fcxa5dpsrdp6cm';
const KEY_PATH_REGTEST =
  'bcrt1p2wsldez5mud2yam29q22wgfh9439spgduvct83k3pm50fcxa5dpsw5tudp';

// tapleaf scripts
// leaf A: a p2pk-ish script pushing a 32 byte x-only key
const LEAF_A =
  '20d85a959b0290bf19bb89ed43c916be835475d013da4b362117393e25a48229b8ac';
const LEAF_B = '51'; // OP_TRUE
const LEAF_C = '52'; // OP_2

// tapleaf hashes
const LEAF_A_HASH =
  '5b75adecf53548f3ec6ad7d78383bf84cc57b55a3127c72b9a2481752dd88b21';
const LEAF_B_HASH =
  'a85b2107f791b26a84e7586c28cec7cb61202ed3d01944d832500f363782d675';
const LEAF_C_HASH =
  'c276fef1386890619b80e10a4a328572d97493add269df1a15a7f89f8ae8ec09';
// tapleaf hash of A when the leaf version is 0xc2
const LEAF_A_HASH_V2 =
  '4db53d41e41519c178875bd3de50c895d07cc90c239cc76cc6d3f4815830cdc';

// tree #1: [A @ 0xc0, B @ 0xc0]
const TREE1_ROOT =
  '87ee479295a15cbd19a2493c872b5b763ac808cb8c198e22f23f7847f8e9c2dd';
const TREE1_OUTPUT_KEY =
  '503b95b9854d2855e59981da7cd31c81e6584a5968e0f64499d3e75f9530383a';
const TREE1_ADDRESS =
  'bc1p2qaetwv9f559teves8d8e5cus8n9sjjedrs0v3ye60n4l9fs8qaqp6xety';
// control block for spending leaf A (sibling = leaf B hash), parity 0
const TREE1_CB_A = `c0${INTERNAL_KEY}${LEAF_B_HASH}`;
// control block for spending leaf B (sibling = leaf A hash), parity 0
const TREE1_CB_B = `c0${INTERNAL_KEY}${LEAF_A_HASH}`;

// tree #2: [A @ 0xc2, B @ 0xc0] (non default leaf version on the A branch)
const TREE2_ROOT =
  'efdb84f7514fc14093a6f6f03c4e45cfce521c7869dd1b0e95d07caedceaf0da';
const TREE2_OUTPUT_KEY =
  '4261f33512bb2792887d830edc3f8b12cab4ee842537cad056bc2d17b709b836';
const TREE2_ADDRESS =
  'bc1pgfslxdgjhvne9zrasv8dc0utzt9tfm5yy5mu45zkhsk30dcfhqmqz2ux39';
const TREE2_CB_A = `c3${INTERNAL_KEY}${LEAF_B_HASH}`; // parity 1

// tree #3: [A @ 0xc2, [B @ 0xc0, C @ 0xc0]] (nested)
const TREE3_ROOT =
  'de66ce5686796ea0dccc5f2ed0dd2d9ab9dd6566f642d198b74521ff89eb2545';
const TREE3_OUTPUT_KEY =
