  version === undefined
    ? { output: fromHex(output) }
    : { output: fromHex(output), version };

const tree1 = () => [leaf(LEAF_A), leaf(LEAF_B)];
const tree2 = () => [leaf(LEAF_A, 0xc2), leaf(LEAF_B)];
const tree3 = () => [leaf(LEAF_A, 0xc2), [leaf(LEAF_B), leaf(LEAF_C)]];

