  initEccLib(ecc);
});

describe('p2tr argument checks', () => {
  test('rejects an empty payment object', () => {
    expect(() => p2tr({})).toThrow(TypeError);
    expect(() => p2tr({})).toThrow('Not enough data');
  });

  test('rejects data that is not sufficient to build a payment', () => {
    // a merkle root on its own is not enough
    expect(() => p2tr({ hash: fromHex(TREE1_ROOT) })).toThrow(
      'Not enough data',
    );
    // a single witness element is not enough either
    expect(() => p2tr({ witness: [fromHex(SIG64)] })).toThrow(
      'Not enough data',
    );
    expect(() => p2tr({ witness: [] })).toThrow('Not enough data');
    expect(() => p2tr({ witness: [] })).toThrow(TypeError);
  });

  test('validates the shape of the provided fields', () => {
    // pubkey must be exactly 32 bytes
    expect(() => p2tr({ pubkey: new Uint8Array(31) })).toThrow(
      /Expected 32 but received 31/,
    );
    // witness must be an array of buffers
    expect(() => p2tr({ pubkey: fromHex(KEY_PATH_OUTPUT_KEY), witness: 'abc' }))
      .toThrow(/Expected Array/);
    // redeemVersion must be a number
    expect(() =>
      p2tr({ internalPubkey: fromHex(INTERNAL_KEY), redeemVersion: 'c0' }),
    ).toThrow(/Expected number/);
    // signatures are restricted to 64 or 65 bytes
    expect(() =>
      p2tr({ pubkey: fromHex(KEY_PATH_OUTPUT_KEY), signature: new Uint8Array(63) }),
    ).toThrow(/Invalid type|Invalid length/);
  });

  test('rejects an invalid script tree', () => {
    // odd leaf versions cannot be represented in the taptree
    expect(() =>
      p2tr({
        internalPubkey: fromHex(INTERNAL_KEY),
        scriptTree: [leaf(LEAF_A, 0xc1), leaf(LEAF_B)],
