describe('p2tr script tree', () => {
  test('computes the merkle root for a two leaf tree', () => {
    const p = keyPath({ scriptTree: tree1() });
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
    expect(toHex(p.pubkey)).toBe(TREE1_OUTPUT_KEY);
    expect(p.address).toBe(TREE1_ADDRESS);
    // no redeem data -> no witness can be constructed
    expect(p.witness).toBeUndefined();
  });

  test('the merkle root does not depend on the leaf order', () => {
    const p = keyPath({ scriptTree: [leaf(LEAF_B), leaf(LEAF_A)] });
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
    expect(p.address).toBe(TREE1_ADDRESS);
  });

  test('honours the leaf version of a single leaf tree', () => {
    const p = keyPath({ scriptTree: leaf(LEAF_A) });
    expect(toHex(p.hash)).toBe(LEAF_A_HASH);
    // leaf version 0xc2 produces a different tapleaf hash
    const p2 = keyPath({ scriptTree: leaf(LEAF_A, 0xc2) });
    expect(toHex(p2.hash)).toBe(LEAF_A_HASH_V2);
    expect(p2.hash).not.toEqual(p.hash);
  });

  test('builds the control block witness for a two leaf tree', () => {
    const p = keyPath({
      scriptTree: tree1(),
      redeem: leaf(LEAF_A),
    });
    expect(p.witness).toHaveLength(2);
    expect(toHex(p.witness[0])).toBe(LEAF_A);
    expect(toHex(p.witness[1])).toBe(TREE1_CB_A);
    expect(p.address).toBe(TREE1_ADDRESS);

    const other = keyPath({
      scriptTree: tree1(),
      redeem: leaf(LEAF_B),
    });
    expect(toHex(other.witness[0])).toBe(LEAF_B);
    expect(toHex(other.witness[1])).toBe(TREE1_CB_B);
  });

  test('uses the leaf version when building the witness', () => {
    const p = keyPath({
      scriptTree: tree2(),
      redeem: leaf(LEAF_A),
      redeemVersion: 0xc2,
    });
    expect(toHex(p.hash)).toBe(TREE2_ROOT);
    expect(toHex(p.pubkey)).toBe(TREE2_OUTPUT_KEY);
    expect(p.address).toBe(TREE2_ADDRESS);
    expect(toHex(p.witness[1])).toBe(TREE2_CB_A);
    // control block encodes 0xc2 | parity
    expect(p.witness[1][0] & 0xfe).toBe(0xc2);

    const viaRedeem = keyPath({
      scriptTree: tree2(),
      redeem: leaf(LEAF_A, 0xc2),
    });
    expect(toHex(viaRedeem.witness[1])).toBe(TREE2_CB_A);
  });

  test('builds control blocks for a nested tree', () => {
    const p = keyPath({ scriptTree: tree3() });
    expect(toHex(p.hash)).toBe(TREE3_ROOT);
    expect(toHex(p.pubkey)).toBe(TREE3_OUTPUT_KEY);
    expect(p.address).toBe(TREE3_ADDRESS);

    const a = keyPath({
      scriptTree: tree3(),
      redeem: leaf(LEAF_A),
      redeemVersion: 0xc2,
    });
    expect(toHex(a.witness[1])).toBe(TREE3_CB_A);

    const b = keyPath({ scriptTree: tree3(), redeem: leaf(LEAF_B) });
    expect(toHex(b.witness[1])).toBe(TREE3_CB_B);

    const c = keyPath({ scriptTree: tree3(), redeem: leaf(LEAF_C) });
    expect(toHex(c.witness[1])).toBe(TREE3_CB_C);
  });

  test('returns no witness when the redeem script is not in the tree', () => {
    const p = keyPath(
      { scriptTree: tree1(), redeem: { output: fromHex('53') } },
      { validate: false },
    );
    expect(p.witness).toBeUndefined();
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
  });

  test('provided witness wins over a computed one', () => {
    const p = keyPath({
      scriptTree: tree1(),
      redeem: leaf(LEAF_A),
      witness: [fromHex(LEAF_B), fromHex(TREE1_CB_B)],
    });
    expect(p.witness).toHaveLength(2);
    expect(toHex(p.witness[0])).toBe(LEAF_B);
  });
});

describe('p2tr witness based spending data', () => {
