const TREE3_ADDRESS =
  'bc1pwvfe4yqj3qnghgpjlg087vd6ya9sf8avem5k9ywjp3uuqgj7jleqluzjlm';
const TREE3_INNER_HASH = LEAF_B_HASH; // branch(B, C) is *not* this; see below
// hash of the inner branch [B, C]
const TREE3_BRANCH_BC =
  '6496f0779f38b871013be71ee7dcce8fcdcc02afc4c688acb159fc5de2fba55e';
const TREE3_CB_A = `c2${INTERNAL_KEY}${TREE3_BRANCH_BC}`; // parity 0
const TREE3_CB_B = `c0${INTERNAL_KEY}${LEAF_C_HASH}${LEAF_A_HASH_V2}`;
const TREE3_CB_C = `c0${INTERNAL_KEY}${LEAF_B_HASH}${LEAF_A_HASH_V2}`;

// a "real enough" 64 byte signature (contents are never verified by p2tr)
const SIG64 = '07'.repeat(64);
const SIG65 = '08'.repeat(65);

const leaf = (output, version) =>
  version === undefined
    ? { output: fromHex(output) }
    : { output: fromHex(output), version };

const tree1 = () => [leaf(LEAF_A), leaf(LEAF_B)];
const tree2 = () => [leaf(LEAF_A, 0xc2), leaf(LEAF_B)];
const tree3 = () => [leaf(LEAF_A, 0xc2), [leaf(LEAF_B), leaf(LEAF_C)]];

const keyPath = extra =>
  p2tr({ internalPubkey: fromHex(INTERNAL_KEY), ...extra });

beforeAll(() => {
  // p2tr needs an ECC implementation for every tweak operation
  initEccLib(ecc);
});

describe('p2tr argument checks', () => {
  test('rejects an empty payment object', () => {
    expect(() => p2tr({})).toThrow(TypeError);
    expect(() => p2tr({})).toThrow('Not enough data');
  });

  test('rejects data that is not sufficient to build a payment', () => {
    // a merkle root on its own is not enough
    expect(() => p2tr({ hash: fromHex(TREE1_ROOT) })).toThrow(
      'Not enough data',
    );
    // a single witness element is not enough either
    expect(() => p2tr({ witness: [fromHex(SIG64)] })).toThrow(
      'Not enough data',
    );
    expect(() => p2tr({ witness: [] })).toThrow('Not enough data');
    expect(() => p2tr({ witness: [] })).toThrow(TypeError);
  });

  test('validates the shape of the provided fields', () => {
    // pubkey must be exactly 32 bytes
    expect(() => p2tr({ pubkey: new Uint8Array(31) })).toThrow(
      /Expected 32 but received 31/,
    );
    // witness must be an array of buffers
    expect(() => p2tr({ pubkey: fromHex(KEY_PATH_OUTPUT_KEY), witness: 'abc' }))
      .toThrow(/Expected Array/);
    // redeemVersion must be a number
    expect(() =>
      p2tr({ internalPubkey: fromHex(INTERNAL_KEY), redeemVersion: 'c0' }),
    ).toThrow(/Expected number/);
    // signatures are restricted to 64 or 65 bytes
    expect(() =>
      p2tr({ pubkey: fromHex(KEY_PATH_OUTPUT_KEY), signature: new Uint8Array(63) }),
    ).toThrow(/Invalid type|Invalid length/);
  });

  test('rejects an invalid script tree', () => {
    // odd leaf versions cannot be represented in the taptree
    expect(() =>
      p2tr({
        internalPubkey: fromHex(INTERNAL_KEY),
        scriptTree: [leaf(LEAF_A, 0xc1), leaf(LEAF_B)],
      }),
    ).toThrow(/Taptree is not of type isTaptree/);
    // trees have exactly two branches
    expect(() =>
      p2tr({
        internalPubkey: fromHex(INTERNAL_KEY),
        scriptTree: [leaf(LEAF_A), leaf(LEAF_B), leaf(LEAF_C)],
      }),
    ).toThrow(/Taptree is not of type isTaptree/);
  });
});

describe('p2tr key path derivation', () => {
  test('derives address, output key and scriptPubKey from an internal key', () => {
    const p = keyPath();
    expect(p.name).toBe('p2tr');
    expect(p.network).toBe(bitcoin);
    expect(toHex(p.pubkey)).toBe(KEY_PATH_OUTPUT_KEY);
    expect(p.address).toBe(KEY_PATH_MAINNET);
    expect(toHex(p.output)).toBe(KEY_PATH_SPK);
    // no script tree and no witness -> no merkle root and no signature
    expect(p.hash).toBeNull();
    expect(p.signature).toBeUndefined();
    expect(p.redeem).toBeUndefined();
    expect(p.redeemVersion).toBe(0xc0);
  });

  test('accepts a precomputed merkle root as the tweak', () => {
    const p = keyPath({ hash: fromHex(TREE1_ROOT) });
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
    expect(toHex(p.pubkey)).toBe(TREE1_OUTPUT_KEY);
    expect(p.address).toBe(TREE1_ADDRESS);
  });

  test('derives everything from an output key alone', () => {
    const p = p2tr({ pubkey: fromHex(KEY_PATH_OUTPUT_KEY) });
    expect(p.address).toBe(KEY_PATH_MAINNET);
    expect(toHex(p.output)).toBe(KEY_PATH_SPK);
    expect(p.output.length).toBe(34);
    expect(p.output[0]).toBe(bscript.OPS.OP_1);
    expect(p.output[1]).toBe(0x20);
    expect(toHex(p.output.slice(2))).toBe(KEY_PATH_OUTPUT_KEY);
    expect(p.internalPubkey).toBeUndefined();
    expect(p.hash).toBeNull();
  });

  test('derives everything from a 34 byte p2tr scriptPubKey', () => {
    const p = p2tr({ output: fromHex(KEY_PATH_SPK) });
    expect(toHex(p.pubkey)).toBe(KEY_PATH_OUTPUT_KEY);
    expect(p.address).toBe(KEY_PATH_MAINNET);
    expect(toHex(p.output)).toBe(KEY_PATH_SPK);
  });

  test('derives everything from a bech32m address', () => {
    const p = p2tr({ address: KEY_PATH_MAINNET });
    expect(toHex(p.pubkey)).toBe(KEY_PATH_OUTPUT_KEY);
    expect(toHex(p.output)).toBe(KEY_PATH_SPK);
    // the address really is a witness v1 encoding of the output key
    const decoded = bech32m.decode(KEY_PATH_MAINNET, 100);
    expect(decoded.prefix).toBe('bc');
    expect(decoded.words[0]).toBe(1);
    expect(toHex(bech32m.fromWords(decoded.words.slice(1)))).toBe(
      KEY_PATH_OUTPUT_KEY,
    );
  });

  test('supports the testnet and regtest networks', () => {
    expect(keyPath({ network: testnet }).address).toBe(KEY_PATH_TESTNET);
    expect(keyPath({ network: regtest }).address).toBe(KEY_PATH_REGTEST);
    expect(p2tr({ pubkey: fromHex(KEY_PATH_OUTPUT_KEY), network: testnet }))
      .toMatchObject({ address: KEY_PATH_TESTNET });
    expect(
      p2tr({ address: KEY_PATH_TESTNET, network: testnet }).pubkey &&
        toHex(p2tr({ address: KEY_PATH_TESTNET, network: testnet }).pubkey),
    ).toBe(KEY_PATH_OUTPUT_KEY);
  });

  test('all input forms agree with each other', () => {
    const fromInternal = keyPath();
    const fromOutput = p2tr({ pubkey: fromInternal.pubkey });
    const fromSpk = p2tr({ output: fromInternal.output });
    const fromAddress = p2tr({ address: fromInternal.address });
    expect(fromOutput.address).toBe(fromInternal.address);
    expect(fromSpk.address).toBe(fromInternal.address);
    expect(fromAddress.address).toBe(fromInternal.address);
    expect(toHex(fromSpk.pubkey)).toBe(toHex(fromInternal.pubkey));
    expect(toHex(fromAddress.pubkey)).toBe(toHex(fromInternal.pubkey));
  });

  test('keeps user supplied extra properties', () => {
    const p = keyPath({ custom: 'value', redeemVersion: 0xc2 });
    expect(p.custom).toBe('value');
    expect(p.redeemVersion).toBe(0xc2);
  });

  test('redeemVersion falls back to redeem.redeemVersion and then 0xc0', () => {
    expect(keyPath().redeemVersion).toBe(0xc0);
    expect(
      keyPath({ redeem: { redeemVersion: 0xc2 } }).redeemVersion,
    ).toBe(0xc2);
    // a falsy explicit redeemVersion is ignored
    expect(keyPath({ redeemVersion: 0 }).redeemVersion).toBe(0xc0);
    // ... but a falsy redeem.redeemVersion is honoured
    expect(keyPath({ redeem: { redeemVersion: 0 } }).redeemVersion).toBe(0);
  });
});

describe('p2tr script tree', () => {
  test('computes the merkle root for a two leaf tree', () => {
    const p = keyPath({ scriptTree: tree1() });
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
    expect(toHex(p.pubkey)).toBe(TREE1_OUTPUT_KEY);
    expect(p.address).toBe(TREE1_ADDRESS);
    // no redeem data -> no witness can be constructed
    expect(p.witness).toBeUndefined();
  });

  test('the merkle root does not depend on the leaf order', () => {
    const p = keyPath({ scriptTree: [leaf(LEAF_B), leaf(LEAF_A)] });
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
    expect(p.address).toBe(TREE1_ADDRESS);
  });

  test('honours the leaf version of a single leaf tree', () => {
    const p = keyPath({ scriptTree: leaf(LEAF_A) });
    expect(toHex(p.hash)).toBe(LEAF_A_HASH);
    // leaf version 0xc2 produces a different tapleaf hash
    const p2 = keyPath({ scriptTree: leaf(LEAF_A, 0xc2) });
    expect(toHex(p2.hash)).toBe(LEAF_A_HASH_V2);
    expect(p2.hash).not.toEqual(p.hash);
  });

  test('builds the control block witness for a two leaf tree', () => {
    const p = keyPath({
      scriptTree: tree1(),
      redeem: leaf(LEAF_A),
    });
    expect(p.witness).toHaveLength(2);
    expect(toHex(p.witness[0])).toBe(LEAF_A);
    expect(toHex(p.witness[1])).toBe(TREE1_CB_A);
    expect(p.address).toBe(TREE1_ADDRESS);

    const other = keyPath({
      scriptTree: tree1(),
      redeem: leaf(LEAF_B),
    });
    expect(toHex(other.witness[0])).toBe(LEAF_B);
    expect(toHex(other.witness[1])).toBe(TREE1_CB_B);
  });

  test('uses the leaf version when building the witness', () => {
    const p = keyPath({
      scriptTree: tree2(),
      redeem: leaf(LEAF_A),
      redeemVersion: 0xc2,
    });
    expect(toHex(p.hash)).toBe(TREE2_ROOT);
    expect(toHex(p.pubkey)).toBe(TREE2_OUTPUT_KEY);
    expect(p.address).toBe(TREE2_ADDRESS);
    expect(toHex(p.witness[1])).toBe(TREE2_CB_A);
    // control block encodes 0xc2 | parity
    expect(p.witness[1][0] & 0xfe).toBe(0xc2);

    const viaRedeem = keyPath({
      scriptTree: tree2(),
      redeem: leaf(LEAF_A, 0xc2),
    });
    expect(toHex(viaRedeem.witness[1])).toBe(TREE2_CB_A);
  });

  test('builds control blocks for a nested tree', () => {
    const p = keyPath({ scriptTree: tree3() });
    expect(toHex(p.hash)).toBe(TREE3_ROOT);
    expect(toHex(p.pubkey)).toBe(TREE3_OUTPUT_KEY);
    expect(p.address).toBe(TREE3_ADDRESS);

    const a = keyPath({
      scriptTree: tree3(),
      redeem: leaf(LEAF_A),
      redeemVersion: 0xc2,
    });
    expect(toHex(a.witness[1])).toBe(TREE3_CB_A);

    const b = keyPath({ scriptTree: tree3(), redeem: leaf(LEAF_B) });
    expect(toHex(b.witness[1])).toBe(TREE3_CB_B);

    const c = keyPath({ scriptTree: tree3(), redeem: leaf(LEAF_C) });
    expect(toHex(c.witness[1])).toBe(TREE3_CB_C);
  });

  test('returns no witness when the redeem script is not in the tree', () => {
    const p = keyPath(
      { scriptTree: tree1(), redeem: { output: fromHex('53') } },
      { validate: false },
    );
    expect(p.witness).toBeUndefined();
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
  });

  test('provided witness wins over a computed one', () => {
    const p = keyPath({
      scriptTree: tree1(),
      redeem: leaf(LEAF_A),
      witness: [fromHex(LEAF_B), fromHex(TREE1_CB_B)],
    });
    expect(p.witness).toHaveLength(2);
    expect(toHex(p.witness[0])).toBe(LEAF_B);
  });
});

describe('p2tr witness based spending data', () => {
  test('recovers the payment from a script path witness', () => {
    const p = p2tr({ witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)] });
    expect(toHex(p.internalPubkey)).toBe(INTERNAL_KEY);
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
    expect(toHex(p.pubkey)).toBe(TREE1_OUTPUT_KEY);
    expect(p.address).toBe(TREE1_ADDRESS);
    expect(toHex(p.redeem.output)).toBe(LEAF_A);
    expect(p.redeem.redeemVersion).toBe(0xc0);
    expect(p.redeem.witness).toHaveLength(0);
    expect(p.signature).toBeUndefined();
  });

  test('recovers the payment from a nested tree witness', () => {
    const witness = [fromHex(LEAF_C), fromHex(TREE3_CB_C)];
    const p = p2tr({ witness });
    expect(toHex(p.internalPubkey)).toBe(INTERNAL_KEY);
    expect(toHex(p.hash)).toBe(TREE3_ROOT);
    expect(p.address).toBe(TREE3_ADDRESS);
    expect(toHex(p.redeem.output)).toBe(LEAF_C);
    expect(toHex(p.redeem.output)).toBe(toHex(witness[0]));
  });

  test('exposes redeem script arguments as redeem.witness', () => {
    const p = p2tr({
      witness: [fromHex('010203'), fromHex(LEAF_A), fromHex(TREE1_CB_A)],
    });
    expect(toHex(p.redeem.output)).toBe(LEAF_A);
    expect(p.redeem.witness).toHaveLength(1);
    expect(toHex(p.redeem.witness[0])).toBe('010203');
    // the annex/control block is not part of the redeem stack
    expect(toHex(p.signature)).toBeUndefined();
  });

  test('recovers a key path signature', () => {
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      witness: [fromHex(SIG64)],
    });
    expect(toHex(p.signature)).toBe(SIG64);
    expect(p.hash).toBeNull();
    expect(p.address).toBe(KEY_PATH_MAINNET);
    expect(p.redeem).toBeUndefined();
  });

  test('accepts a 65 byte key path signature', () => {
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      signature: fromHex(SIG65),
    });
    expect(toHex(p.signature)).toBe(SIG65);
    expect(p.witness).toHaveLength(1);
    expect(toHex(p.witness[0])).toBe(SIG65);
  });

  test('ignores a trailing annex element', () => {
    const annex = fromHex('50010203');
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      witness: [fromHex(SIG64), annex],
    });
    // signature is taken from the annex stripped witness
    expect(toHex(p.signature)).toBe(SIG64);
    // ... but the user supplied witness is returned untouched
    expect(p.witness).toHaveLength(2);
    expect(toHex(p.witness[1])).toBe(toHex(annex));

    const scriptPath = p2tr({
      witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A), annex],
    });
    expect(toHex(scriptPath.hash)).toBe(TREE1_ROOT);
    expect(toHex(scriptPath.internalPubkey)).toBe(INTERNAL_KEY);
    expect(toHex(scriptPath.redeem.output)).toBe(LEAF_A);
  });

  test('builds a key path witness from a bare signature', () => {
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      signature: fromHex(SIG64),
    });
    expect(p.witness).toHaveLength(1);
    expect(toHex(p.witness[0])).toBe(SIG64);
  });
});

describe('p2tr address validation', () => {
  test('rejects an address for another network', () => {
    expect(() => p2tr({ address: KEY_PATH_TESTNET })).toThrow(TypeError);
    expect(() => p2tr({ address: KEY_PATH_TESTNET })).toThrow(
      'Invalid prefix or Network mismatch',
    );
    expect(() =>
      p2tr({ address: KEY_PATH_MAINNET, network: testnet }),
    ).toThrow('Invalid prefix or Network mismatch');
  });

  test('rejects addresses with the wrong witness version', () => {
    // witness v0 (a p2wpkh address)
    const v0words = bech32.toWords(new Uint8Array(20).fill(2));
    v0words.unshift(0);
    const v0 = bech32.encode('bc', v0words);
    expect(() => p2tr({ address: v0 })).toThrow('Invalid address version');

    // witness v2
    const v2words = bech32m.toWords(new Uint8Array(32).fill(1));
    v2words.unshift(2);
    const v2 = bech32m.encode('bc', v2words);
    expect(() => p2tr({ address: v2 })).toThrow('Invalid address version');
  });

  test('rejects a witness v1 address with the wrong data length', () => {
    const words = bech32m.toWords(new Uint8Array(20).fill(1));
    words.unshift(1);
    const shortData = bech32m.encode('bc', words);
    expect(() => p2tr({ address: shortData })).toThrow(TypeError);
    expect(() => p2tr({ address: shortData })).toThrow('Invalid address data');
  });

  test('rejects malformed addresses', () => {
    expect(() => p2tr({ address: 'not-an-address' })).toThrow(
      /No separator character/,
    );
  });
});

describe('p2tr pubkey and output validation', () => {
  test('rejects a pubkey that does not match the address', () => {
    expect(() =>
      p2tr({ address: KEY_PATH_MAINNET, pubkey: fromHex(OTHER_KEY) }),
    ).toThrow('Pubkey mismatch');
  });

  test('rejects a pubkey that does not match the output', () => {
    expect(() =>
      p2tr({ output: fromHex(KEY_PATH_SPK), pubkey: fromHex(OTHER_KEY) }),
    ).toThrow('Pubkey mismatch');
  });

  test('accepts matching pubkey and output', () => {
    const p = p2tr({
      output: fromHex(KEY_PATH_SPK),
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
    });
    expect(p.address).toBe(KEY_PATH_MAINNET);
  });

  test('rejects malformed outputs', () => {
    // wrong length is caught by the argument schema
    expect(() => p2tr({ output: new Uint8Array(33) })).toThrow(
      /Expected 34 but received 33/,
    );
    // OP_0 instead of OP_1
    expect(() =>
      p2tr({ output: Uint8Array.from([0x00, 0x20, ...new Uint8Array(32)]) }),
    ).toThrow('Output is invalid');
    // wrong push length byte
    expect(() =>
      p2tr({ output: Uint8Array.from([0x51, 0x1f, ...new Uint8Array(32)]) }),
    ).toThrow('Output is invalid');
  });

  test('rejects a scriptPubKey whose key is not on the curve', () => {
    expect(() =>
      p2tr({ output: Uint8Array.from([0x51, 0x20, ...new Uint8Array(32)]) }),
    ).toThrow('Invalid pubkey for p2tr');
    expect(() => p2tr({ pubkey: new Uint8Array(32) })).toThrow(
      'Invalid pubkey for p2tr',
    );
  });
});

describe('p2tr hash and redeem validation', () => {
  test('rejects a merkle root that does not match the script tree', () => {
    expect(() =>
      keyPath({ scriptTree: tree1(), hash: new Uint8Array(32) }),
    ).toThrow('Hash mismatch');
  });

  test('accepts a merkle root that matches the script tree', () => {
    const p = keyPath({ scriptTree: tree1(), hash: fromHex(TREE1_ROOT) });
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
    expect(p.address).toBe(TREE1_ADDRESS);
  });

  test('rejects a redeem script that is not in the tree', () => {
    expect(() =>
      keyPath({ scriptTree: tree1(), redeem: { output: fromHex('53') } }),
    ).toThrow('Redeem script not in tree');
  });

  test('rejects an empty redeem script', () => {
    expect(() =>
      p2tr({
        witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        redeem: { output: new Uint8Array(0) },
      }),
    ).toThrow('Redeem.output is invalid');
  });

  test('rejects a redeem script that does not match the witness', () => {
    expect(() =>
      p2tr({
        witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        redeem: leaf(LEAF_B),
      }),
    ).toThrow('Redeem.output and witness mismatch');
  });

  test('rejects a redeem version that does not match the witness', () => {
    expect(() =>
      p2tr({
        witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        redeem: { output: fromHex(LEAF_A), redeemVersion: 0xc2 },
      }),
    ).toThrow('Redeem.redeemVersion and witness mismatch');
  });

  test('accepts a matching redeem version', () => {
    const p = p2tr({
      witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
      redeem: { output: fromHex(LEAF_A), redeemVersion: 0xc0 },
    });
    expect(p.redeem.redeemVersion).toBe(0xc0);
    expect(toHex(p.redeem.output)).toBe(LEAF_A);
  });

  test('rejects redeem stack data that does not match the witness', () => {
    expect(() =>
      p2tr({
        witness: [fromHex('010203'), fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        redeem: { witness: [fromHex('09')] },
      }),
    ).toThrow('Redeem.witness and witness mismatch');
  });

  test('accepts a matching redeem stack', () => {
    const p = p2tr({
      witness: [fromHex('010203'), fromHex(LEAF_A), fromHex(TREE1_CB_A)],
      redeem: { witness: [fromHex('010203')] },
    });
    expect(p.redeem.witness).toHaveLength(1);
    expect(toHex(p.redeem.witness[0])).toBe('010203');
  });
});

describe('p2tr signature validation', () => {
  test('rejects a signature that does not match the witness', () => {
    expect(() =>
      p2tr({
        pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
        witness: [fromHex(SIG64)],
        signature: fromHex('09'.repeat(64)),
      }),
    ).toThrow('Signature mismatch');
  });

  test('accepts a matching signature', () => {
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      witness: [fromHex(SIG64)],
      signature: fromHex(SIG64),
    });
    expect(toHex(p.signature)).toBe(SIG64);
  });
});

describe('p2tr control block validation', () => {
  test('rejects a control block that is too short', () => {
    const shortCb = Uint8Array.from([0xc0, ...new Uint8Array(10)]);
    expect(() =>
      p2tr({ witness: [fromHex(LEAF_A), shortCb] }),
    ).toThrow(TypeError);
    expect(() => p2tr({ witness: [fromHex(LEAF_A), shortCb] })).toThrow(
      'The control-block length is too small. Got 11, expected min 33.',
    );
  });

  test('rejects a control block with a partial merkle path', () => {
    const cb = fromHex(`c0${INTERNAL_KEY}00`);
    expect(() => p2tr({ witness: [fromHex(LEAF_A), cb] })).toThrow(
      'The control-block length of 34 is incorrect!',
    );
  });

  test('rejects a merkle path that is too long', () => {
    const cb = new Uint8Array(33 + 32 * 129).fill(3);
    cb[0] = 0xc0;
    cb.set(fromHex(INTERNAL_KEY), 1);
    expect(() => p2tr({ witness: [fromHex(LEAF_A), cb] })).toThrow(
      'The script path is too long. Got 129, expected max 128.',
    );
  });

  test('accepts a maximum depth merkle path', () => {
    const cb = new Uint8Array(33 + 32 * 128).fill(3);
    cb[0] = 0xc0;
    cb.set(fromHex(INTERNAL_KEY), 1);
    const p = p2tr({ witness: [fromHex(LEAF_A), cb] });
    expect(toHex(p.internalPubkey)).toBe(INTERNAL_KEY);
    expect(p.address).toBe(
      'bc1plqydgkz4q5swfuksauy9vud5thsk8fq2n5fk2uls4869l5tdvgeqcvhpjw',
    );
  });

  test('rejects a control block with a different internal pubkey', () => {
    expect(() =>
      p2tr({
        witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        internalPubkey: fromHex(OTHER_KEY),
      }),
    ).toThrow('Internal pubkey mismatch');
  });

  test('rejects a control block with an invalid internal pubkey', () => {
    const cb = Uint8Array.from([0xc0, ...new Uint8Array(32)]);
    expect(() => p2tr({ witness: [fromHex(LEAF_A), cb] })).toThrow(
      'Invalid internalPubkey for p2tr witness',
    );
  });

  test('rejects a control block that commits to another output key', () => {
    expect(() =>
      p2tr({
        witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
        pubkey: fromHex(OTHER_KEY),
      }),
    ).toThrow('Pubkey mismatch for p2tr witness');
  });

  test('rejects a control block with the wrong parity', () => {
    const flipped = fromHex(TREE1_CB_A);
    flipped[0] = flipped[0] ^ 1;
    let err;
    try {
      p2tr({ witness: [fromHex(LEAF_A), flipped] });
    } catch (e) {
      err = e;
    }
    expect(err).toBeInstanceOf(Error);
    expect(err).not.toBeInstanceOf(TypeError);
    expect(err.message).toBe('Incorrect parity');
  });

  test('accepts a witness with the same payment data attached', () => {
    const p = p2tr({
      witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)],
      internalPubkey: fromHex(INTERNAL_KEY),
      hash: fromHex(TREE1_ROOT),
      pubkey: fromHex(TREE1_OUTPUT_KEY),
      address: TREE1_ADDRESS,
    });
    expect(p.address).toBe(TREE1_ADDRESS);
    expect(toHex(p.output)).toBe(`5120${TREE1_OUTPUT_KEY}`);
  });
});

describe('p2tr without validation', () => {
  test('skips extended validation when validate is false', () => {
    // the testnet address would normally be rejected for the mainnet network
    const p = p2tr({ address: KEY_PATH_TESTNET }, { validate: false });
    expect(p.address).toBe(KEY_PATH_TESTNET);
    expect(toHex(p.pubkey)).toBe(KEY_PATH_OUTPUT_KEY);
    expect(toHex(p.output)).toBe(KEY_PATH_SPK);
    expect(p.network).toBe(bitcoin);
  });

  test('does not check the output script format when validate is false', () => {
    const bad = Uint8Array.from([0x00, 0x20, ...fromHex(KEY_PATH_OUTPUT_KEY)]);
    const p = p2tr({ output: bad }, { validate: false });
    expect(toHex(p.output)).toBe(toHex(bad));
    expect(toHex(p.pubkey)).toBe(KEY_PATH_OUTPUT_KEY);
    expect(p.address).toBe(KEY_PATH_MAINNET);
  });

  test('still rejects an invalid merkle root when validate is false', () => {
    // a provided hash is used as-is, so the resulting key is different
    const p = p2tr(
      { internalPubkey: fromHex(INTERNAL_KEY), hash: new Uint8Array(32) },
      { validate: false },
    );
    expect(toHex(p.hash)).toBe('00'.repeat(32));
    expect(p.address).not.toBe(KEY_PATH_MAINNET);
  });
});
