describe('p2tr key path derivation', () => {
  test('derives address, output key and scriptPubKey from an internal key', () => {
    const p = keyPath();
    expect(p.name).toBe('p2tr');
    expect(p.network).toBe(bitcoin);
    expect(toHex(p.pubkey)).toBe(KEY_PATH_OUTPUT_KEY);
    expect(p.address).toBe(KEY_PATH_MAINNET);
    expect(toHex(p.output)).toBe(KEY_PATH_SPK);
    // no script tree and no witness -> no merkle root and no signature
    expect(p.hash).toBeNull();
    expect(p.signature).toBeUndefined();
    expect(p.redeem).toBeUndefined();
    expect(p.redeemVersion).toBe(0xc0);
  });

  test('accepts a precomputed merkle root as the tweak', () => {
    const p = keyPath({ hash: fromHex(TREE1_ROOT) });
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
    expect(toHex(p.pubkey)).toBe(TREE1_OUTPUT_KEY);
    expect(p.address).toBe(TREE1_ADDRESS);
  });

  test('derives everything from an output key alone', () => {
    const p = p2tr({ pubkey: fromHex(KEY_PATH_OUTPUT_KEY) });
    expect(p.address).toBe(KEY_PATH_MAINNET);
    expect(toHex(p.output)).toBe(KEY_PATH_SPK);
    expect(p.output.length).toBe(34);
    expect(p.output[0]).toBe(bscript.OPS.OP_1);
    expect(p.output[1]).toBe(0x20);
    expect(toHex(p.output.slice(2))).toBe(KEY_PATH_OUTPUT_KEY);
    expect(p.internalPubkey).toBeUndefined();
    expect(p.hash).toBeNull();
  });

  test('derives everything from a 34 byte p2tr scriptPubKey', () => {
    const p = p2tr({ output: fromHex(KEY_PATH_SPK) });
    expect(toHex(p.pubkey)).toBe(KEY_PATH_OUTPUT_KEY);
    expect(p.address).toBe(KEY_PATH_MAINNET);
    expect(toHex(p.output)).toBe(KEY_PATH_SPK);
  });

  test('derives everything from a bech32m address', () => {
    const p = p2tr({ address: KEY_PATH_MAINNET });
    expect(toHex(p.pubkey)).toBe(KEY_PATH_OUTPUT_KEY);
    expect(toHex(p.output)).toBe(KEY_PATH_SPK);
    // the address really is a witness v1 encoding of the output key
    const decoded = bech32m.decode(KEY_PATH_MAINNET, 100);
    expect(decoded.prefix).toBe('bc');
    expect(decoded.words[0]).toBe(1);
    expect(toHex(bech32m.fromWords(decoded.words.slice(1)))).toBe(
      KEY_PATH_OUTPUT_KEY,
    );
  });

  test('supports the testnet and regtest networks', () => {
    expect(keyPath({ network: testnet }).address).toBe(KEY_PATH_TESTNET);
    expect(keyPath({ network: regtest }).address).toBe(KEY_PATH_REGTEST);
    expect(p2tr({ pubkey: fromHex(KEY_PATH_OUTPUT_KEY), network: testnet }))
      .toMatchObject({ address: KEY_PATH_TESTNET });
    expect(
      p2tr({ address: KEY_PATH_TESTNET, network: testnet }).pubkey &&
        toHex(p2tr({ address: KEY_PATH_TESTNET, network: testnet }).pubkey),
    ).toBe(KEY_PATH_OUTPUT_KEY);
  });

  test('only requires the bech32 prefix from a network object', () => {
    const minimal = { bech32: 'tb' };
    const p = keyPath({ network: minimal });
    expect(p.address).toBe(KEY_PATH_TESTNET);
    expect(p.network).toBe(minimal);
    // ... and the same minimal network passes validation for its addresses
    expect(p2tr({ address: KEY_PATH_TESTNET, network: minimal }).address).toBe(
      KEY_PATH_TESTNET,
    );
  });

  test('all input forms agree with each other', () => {
    const fromInternal = keyPath();
    const fromOutput = p2tr({ pubkey: fromInternal.pubkey });
    const fromSpk = p2tr({ output: fromInternal.output });
    const fromAddress = p2tr({ address: fromInternal.address });
    expect(fromOutput.address).toBe(fromInternal.address);
    expect(fromSpk.address).toBe(fromInternal.address);
    expect(fromAddress.address).toBe(fromInternal.address);
    expect(toHex(fromSpk.pubkey)).toBe(toHex(fromInternal.pubkey));
    expect(toHex(fromAddress.pubkey)).toBe(toHex(fromInternal.pubkey));
