    expect(p.custom).toBe('value');
    expect(p.redeemVersion).toBe(0xc2);
  });

  test('redeemVersion falls back to redeem.redeemVersion and then 0xc0', () => {
    // default tapscript leaf version
    expect(keyPath().redeemVersion).toBe(0xc0);
    expect(keyPath({ redeemVersion: 0xc2 }).redeemVersion).toBe(0xc2);
