describe('p2tr witness based spending data', () => {
  test('recovers the payment from a script path witness', () => {
    const p = p2tr({ witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A)] });
    expect(toHex(p.internalPubkey)).toBe(INTERNAL_KEY);
    expect(toHex(p.hash)).toBe(TREE1_ROOT);
    expect(toHex(p.pubkey)).toBe(TREE1_OUTPUT_KEY);
    expect(p.address).toBe(TREE1_ADDRESS);
    expect(toHex(p.redeem.output)).toBe(LEAF_A);
    expect(p.redeem.redeemVersion).toBe(0xc0);
    expect(p.redeem.witness).toHaveLength(0);
    expect(p.signature).toBeUndefined();
  });

  test('recovers the payment from a nested tree witness', () => {
    const witness = [fromHex(LEAF_C), fromHex(TREE3_CB_C)];
    const p = p2tr({ witness });
    expect(toHex(p.internalPubkey)).toBe(INTERNAL_KEY);
    expect(toHex(p.hash)).toBe(TREE3_ROOT);
    expect(p.address).toBe(TREE3_ADDRESS);
    expect(toHex(p.redeem.output)).toBe(LEAF_C);
    expect(toHex(p.redeem.output)).toBe(toHex(witness[0]));
  });

  test('exposes redeem script arguments as redeem.witness', () => {
    const p = p2tr({
      witness: [fromHex('010203'), fromHex(LEAF_A), fromHex(TREE1_CB_A)],
    });
    expect(toHex(p.redeem.output)).toBe(LEAF_A);
    expect(p.redeem.witness).toHaveLength(1);
    expect(toHex(p.redeem.witness[0])).toBe('010203');
    // script path spends carry no script signature
    expect(p.signature).toBeUndefined();
  });

  test('recovers a key path signature', () => {
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      witness: [fromHex(SIG64)],
    });
    expect(toHex(p.signature)).toBe(SIG64);
    expect(p.hash).toBeNull();
    expect(p.address).toBe(KEY_PATH_MAINNET);
    expect(p.redeem).toBeUndefined();
  });

  test('accepts a 65 byte key path signature', () => {
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      signature: fromHex(SIG65),
    });
    expect(toHex(p.signature)).toBe(SIG65);
    expect(p.witness).toHaveLength(1);
    expect(toHex(p.witness[0])).toBe(SIG65);
  });

  test('ignores a trailing annex element', () => {
    const annex = fromHex('50010203');
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      witness: [fromHex(SIG64), annex],
    });
    // signature is taken from the annex stripped witness
    expect(toHex(p.signature)).toBe(SIG64);
    // ... but the user supplied witness is returned untouched
    expect(p.witness).toHaveLength(2);
    expect(toHex(p.witness[1])).toBe(toHex(annex));

    const scriptPath = p2tr({
      witness: [fromHex(LEAF_A), fromHex(TREE1_CB_A), annex],
    });
    expect(toHex(scriptPath.hash)).toBe(TREE1_ROOT);
    expect(toHex(scriptPath.internalPubkey)).toBe(INTERNAL_KEY);
    expect(toHex(scriptPath.redeem.output)).toBe(LEAF_A);
  });

  test('builds a key path witness from a bare signature', () => {
    const p = p2tr({
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
      signature: fromHex(SIG64),
    });
    expect(p.witness).toHaveLength(1);
    expect(toHex(p.witness[0])).toBe(SIG64);
  });
});

describe('p2tr address validation', () => {
  test('rejects an address for another network', () => {
    expect(() => p2tr({ address: KEY_PATH_TESTNET })).toThrow(TypeError);
    expect(() => p2tr({ address: KEY_PATH_TESTNET })).toThrow(
      'Invalid prefix or Network mismatch',
    );
    expect(() => p2tr({ address: KEY_PATH_MAINNET, network: testnet })).toThrow(
      'Invalid prefix or Network mismatch',
    );
  });

  test('rejects addresses with the wrong witness version', () => {
    // witness v0 (a p2wpkh address)
    const v0words = bech32.toWords(new Uint8Array(20).fill(2));
    v0words.unshift(0);
    const v0 = bech32.encode('bc', v0words);
    expect(() => p2tr({ address: v0 })).toThrow('Invalid address version');

    // witness v2
    const v2words = bech32m.toWords(new Uint8Array(32).fill(1));
    v2words.unshift(2);
    const v2 = bech32m.encode('bc', v2words);
    expect(() => p2tr({ address: v2 })).toThrow('Invalid address version');
  });

  test('rejects a witness v1 address with the wrong data length', () => {
    const words = bech32m.toWords(new Uint8Array(20).fill(1));
    words.unshift(1);
    const shortData = bech32m.encode('bc', words);
    expect(() => p2tr({ address: shortData })).toThrow(TypeError);
    expect(() => p2tr({ address: shortData })).toThrow('Invalid address data');
  });

  test('rejects malformed addresses', () => {
    expect(() => p2tr({ address: 'not-an-address' })).toThrow(
      /No separator character/,
    );
  });
});

describe('p2tr pubkey and output validation', () => {
  test('rejects a pubkey that does not match the address', () => {
    expect(() =>
      p2tr({ address: KEY_PATH_MAINNET, pubkey: fromHex(OTHER_KEY) }),
    ).toThrow('Pubkey mismatch');
  });

  test('rejects a pubkey that does not match the output', () => {
    expect(() =>
      p2tr({ output: fromHex(KEY_PATH_SPK), pubkey: fromHex(OTHER_KEY) }),
    ).toThrow('Pubkey mismatch');
  });

  test('rejects an internal pubkey that does not match the output key', () => {
    expect(() =>
      p2tr({
        internalPubkey: fromHex(OTHER_KEY),
        scriptTree: tree1(),
        pubkey: fromHex(TREE1_OUTPUT_KEY),
      }),
    ).toThrow('Pubkey mismatch');
    expect(() =>
      p2tr({
        internalPubkey: fromHex(OTHER_KEY),
        scriptTree: tree1(),
        address: TREE1_ADDRESS,
      }),
    ).toThrow('Pubkey mismatch');
    // the matching internal key is accepted
    const p = p2tr({
      internalPubkey: fromHex(INTERNAL_KEY),
      scriptTree: tree1(),
      address: TREE1_ADDRESS,
    });
    expect(toHex(p.pubkey)).toBe(TREE1_OUTPUT_KEY);
  });

  test('accepts matching pubkey and output', () => {
    const p = p2tr({
      output: fromHex(KEY_PATH_SPK),
      pubkey: fromHex(KEY_PATH_OUTPUT_KEY),
    });
    expect(p.address).toBe(KEY_PATH_MAINNET);
  });

