{"command": "cd /testbed; cat > /tmp/jt/probe3.mjs <<'EOF'
import { Transaction } from '/testbed/src/cjs/index.cjs';
import { fromHex } from '/testbed/node_modules/uint8array-tools/src/cjs/index.cjs';
const tx = new Transaction();
tx.addInput(new Uint8Array(32).fill(1), 0);
tx.addInput(new Uint8Array(32).fill(2), 1);
tx.addOutput(fromHex('0014' + '00'.repeat(20)), 1000n);
const s = [fromHex('0014' + '11'.repeat(20)), fromHex('0014' + '22'.repeat(20))];
const vals = [1000n, 2000n];
const tryIt = (label, f) => { try { const r = f(); console.log(label, 'OK', r && r.length); } catch (e) { console.log(label, 'THROW', e.constructor.name, e.name, e.message.slice(0,120)); } };
tryIt('no outs NONE', () => { const t = new Transaction(); t.addInput(new Uint8Array(32).fill(1),0); return t.hashForWitnessV1(0, [s[0]], [1n], 2); });
tryIt('no outs SINGLE', () => { const t = new Transaction(); t.addInput(new Uint8Array(32).fill(1),0); return t.hashForWitnessV1(0, [s[0]], [1n], 3); });
tryIt('no outs ALL', () => { const t = new Transaction(); t.addInput(new Uint8Array(32).fill(1),0); return t.hashForWitnessV1(0, [s[0]], [1n], 1); });
tryIt('short vals', () => tx.hashForWitnessV1(0, s, [1n], 1));
tryIt('bad inIndex', () => tx.hashForWitnessV1(-1, s, vals, 1));
tryIt('bad hashType', () => tx.hashForWitnessV1(0, s, vals, 0x100000000));
tryIt('num value', () => tx.hashForWitnessV1(0, s, [1, 2], 1));
tryIt('array script', () => tx.hashForWitnessV1(0, [[1,2], s[1]], vals, 1));
tryIt('single oob', () => tx.hashForWitnessV1(1, s, vals, 3));
tryIt('seqs', () => tx.hashForWitnessV1(0, s, vals, 0x81));
console.log('tmphash', Buffer.from(tx.hashForWitnessV1(0,s,vals,0x81)).toString('hex'));
EOF
node /tmp/jt/probe3.mjs 2>&1 | tail -20"}

