cd /testbed; cat > test/cjs/transaction/hashForWitnessV1.test.js <<'EOF'
import { describe, it, expect } from '@jest/globals';
import * as ecc from 'tiny-secp256k1';
import { Transaction } from '../../../src/cjs/index.cjs';

const fromHex = hex => Uint8Array.from(Buffer.from(hex, 'hex'));
const toHex = bytes => Buffer.from(bytes).toString('hex');

const SIGHASH_DEFAULT = Transaction.SIGHASH_DEFAULT; // 0x00
const SIGHASH_ALL = Transaction.SIGHASH_ALL; // 0x01
const SIGHASH_NONE = Transaction.SIGHASH_NONE; // 0x02
const SIGHASH_SINGLE = Transaction.SIGHASH_SINGLE; // 0x03
const SIGHASH_ANYONECANPAY = Transaction.SIGHASH_ANYONECANPAY; // 0x80

// ---------------------------------------------------------------------------
// Helpers used to build deterministic test transactions
// ---------------------------------------------------------------------------

const hashOf = byte => new Uint8Array(32).fill(byte);

// OP_1 <32-byte x-only pubkey>: 34 bytes, the size assumed by BIP341 for a
// taproot prevout script (relevant for SIGHASH_ANYONECANPAY sizing).
const p2trScript = byte => {
  const script = new Uint8Array(34);
  script[0] = 0x51; // OP_1
  script[1] = 0x20; // push 32 bytes
  script.set(hashOf(byte), 2);
  return script;
};

const p2wpkhScript = byte => {
  const script = new Uint8Array(22);
  script[0] = 0x00; // OP_0
  script[1] = 0x14; // push 20 bytes
  script.set(new Uint8Array(20).fill(byte), 2);
  return script;
};

function makeTx({
  version = 2,
  locktime = 0,
  inputHashes = [0x11, 0x22],
  outputs = [
    { value: 100000n, scriptByte: 0xa1 },
    { value: 200000n, scriptByte: 0xa2 },
  ],
} = {}) {
  const tx = new Transaction();
  tx.version = version;
  tx.locktime = locktime;
  inputHashes.forEach((byte, index) =>
    tx.addInput(hashOf(byte), index, 0xfffffffd - index),
  );
  outputs.forEach(({ value, scriptByte }) =>
    tx.addOutput(p2trScript(scriptByte), value),
  );
  return tx;
}

function makeTxWithoutOutputs() {
  const tx = new Transaction();
  tx.addInput(hashOf(0x11), 0);
  return tx;
}

const prevScripts = () => [p2trScript(0xc1), p2trScript(0xc2)];
const prevValues = () => [50000n, 60000n];
const leafHash = () => hashOf(0xaa);
const annex = () => fromHex('50' + 'cc'.repeat(5)); // BIP341 annexes start with 0x50

const digestOf = (tx, inIndex, hashType, extra = {}) =>
  toHex(
    tx.hashForWitnessV1(
      inIndex,
      extra.prevScripts ?? prevScripts(),
      extra.prevValues ?? prevValues(),
      hashType,
      extra.leafHash,
      extra.annex,
    ),
  );

// ---------------------------------------------------------------------------
// BIP341 wallet test vectors (key path spending, no leaf hash / annex)
// https://github.com/bitcoin/bips/blob/master/bip-0341.mediawiki#test-vectors
// ---------------------------------------------------------------------------

const BIP341_TX_HEX =
  '';

const BIP341_PREVOUTS = [
  ['512053a1f6e454df1aa2776a2814a721372d6258050de330b3c6d10ee8f4e0dda343', 420000000n],
  ['5120147c9c57132f6e7ecddba9800bb0c4449251c92a1e60371ee77557b6620f3ea3', 462000000n],
  ['76a914751e76e8199196d454941c45d1b3a323f1433bd688ac', 294000000n],
  ['5120e4d810fd50586274face62b8a807eb9719cef49c04177cc6b76a9a4251d5450e', 504000000n],
  ['512091b64d5324723a985170e4dc5a0f84c041804f2cd12660fa5dec09fc21783605', 630000000n],
  ['00147dd65592d0ab2fe0d0257d571abf032cd9db93dc', 378000000n],
  ['512075169f4001aa68f15bbed28b218df1d0a62cbbcf1188c6665110c293c907b831', 672000000n],
  ['51200f63ca2c7639b9bb4be0465cc0aa3ee78a0761ba5f5f7d6ff8eab340f09da561', 546000000n],
  ['5120053690babeabbb7850c32eead0acf8df990ced79f7a31e358fabf2658b4bc587', 588000000n],
];

const bip341Scripts = () => BIP341_PREVOUTS.map(([script]) => fromHex(script));
const bip341Values = () => BIP341_PREVOUTS.map(([, value]) => value);

const BIP341_CASES = [
  { vin: 0, hashType: 0x03, expected: '7e584883b084ace0469c6962a9a7d2a9060e1f3c218ab40d32c77651482122bc' },
  { vin: 1, hashType: 0x83, expected: '325a644af47e8a5a2591cda0ab0723978537318f10e6a63d4eed783b96a71a4d' },
  { vin: 3, hashType: 0x01, expected: '6ffd256e108685b41831385f57eebf2fca041bc6b5e607ea11b3e03d4cf9d9ba' },
  { vin: 4, hashType: 0x00, expected: '9f90136737540ccc18707e1fd398ad222a1a7e4dd65cbfd22dbe4660191efa58' },
  { vin: 6, hashType: 0x02, expected: '835c9ab6084ed9a8ae9b7cda21e0aa797aca3b76a54bd1e3c7db093f6c57e23f' },
  { vin: 7, hashType: 0x82, expected: 'df1cca638283c667084b8ffe6bf6e116cc5a53cf7ae1202c5fee45a9085f1ba5' },
  { vin: 8, hashType: 0x81, expected: '30319859ca79ea1b7a9782e9daebc46e4ca4ca2bc04c9c53b2ec87fa83a526bd' },
];

// ---------------------------------------------------------------------------
// A BIP371 PSBT carrying real tapscript (leaf hash) signatures. The schnorr
// signatures are verified against the digest produced by hashForWitnessV1,
// which independently proves the leaf hash / BIP342 extension is committed to.
// ---------------------------------------------------------------------------

const TAPSCRIPT_TX_HEX =
  '0200000001053618b8ff1d338437cd381dce8944d4cb33b1260e52017631b61b5694c36eba0000000000ffffffff01801a060000000000225120df9b0b19ea415d46d1f775dfc4325c601087a8d563c3f8e880e80f55d89cd54800000000';
const TAPSCRIPT_PREVOUT_SCRIPT =
  '5120559c78fad1de39171bd230c99cecadace9cd3862f5b92d0c74c520d4641e4b5e';
const TAPSCRIPT_PREVOUT_VALUE = 420000n;
const TAPSCRIPT_LEAF_HASH =
  'aea23415d65d2882cb2d981154af0bf419f68a353a21ca2aab22262885addccb';
const TAPSCRIPT_DIGEST =
  '99942b0689ef782c5be603d2189325228bc999e144e10c65423f29e98fd9e938';

const TAPSCRIPT_SIGS = [
  {
    pubkey: '395f8129dd63b4a5c2f12124eaa05b7a7ed30f70e51fb93305deecc542e7f9eb',
    signature:
      '0376a506853b2010a4064f4e1c3d7013c7c9238cbe95b9d3463e3c7bc000c1133beeadd19a5ebbf6a0b31af100280b3df5434c6971d02218067d13f5d4032526',
  },
  {
    pubkey: '8f891aaf2e2d7b146178c54a87e2aeddd9d1d686692257928e67cf08174ff375',
    signature:
      'd8259e8bbfb1593c80516457d5805e6fde07118909d3f1a33cd90e483e4c24cd9ac6a384e165b96fba71bffa1bbc64fb89ad453eb976feb3dadcc121fe062848',
  },
  {
    pubkey: 'a8ab37bc1609d834c3913b3538dad1c84d7f9b6a835ffc175777915a37ae3572',
    signature:
      '47d0e549008389536e12718cccc1ee1bba69dd5fcb06311c25e31571c7ae6e4f25338524b836a139f0b904e8cff676016fd4113ecea7e592a0766f5b8b73ccb8',
  },
];

// ---------------------------------------------------------------------------

describe('Transaction.hashForWitnessV1', () => {
  describe('BIP341 test vectors', () => {
    it.each(BIP341_CASES)(
      'matches the published sighash for vin $vin with hash type $hashType',
      ({ vin, hashType, expected }) => {
        const tx = Transaction.fromHex(BIP341_TX_HEX);
        const digest = tx.hashForWitnessV1(
          vin,
          bip341Scripts(),
          bip341Values(),
          hashType,
        );
        expect(digest).toBeInstanceOf(Uint8Array);
        expect(digest).toHaveLength(32);
        expect(toHex(digest)).toBe(expected);
      },
    );

    it('is deterministic for repeated calls', () => {
      const tx = Transaction.fromHex(BIP341_TX_HEX);
      const first = tx.hashForWitnessV1(0, bip341Scripts(), bip341Values(), 0x03);
      const second = tx.hashForWitnessV1(0, bip341Scripts(), bip341Values(), 0x03);
      expect(toHex(second)).toBe(toHex(first));
    });
  });

  describe('hash type semantics', () => {
    it('treats SIGHASH_DEFAULT exactly like SIGHASH_ALL', () => {
      const tx = Transaction.fromHex(BIP341_TX_HEX);
      for (const vin of [0, 1, 4, 8]) {
        expect(digestOf(tx, vin, SIGHASH_DEFAULT, {
          prevScripts: bip341Scripts(),
          prevValues: bip341Values(),
        })).toBe(
          digestOf(tx, vin, SIGHASH_ALL, {
            prevScripts: bip341Scripts(),
            prevValues: bip341Values(),
          }),
        );
      }
    });

    it('treats SIGHASH_DEFAULT like SIGHASH_ALL when a leaf hash and annex are supplied', () => {
      const tx = makeTx();
      const extra = { leafHash: leafHash(), annex: annex() };
      expect(digestOf(tx, 0, SIGHASH_DEFAULT, extra)).toBe(
        digestOf(tx, 0, SIGHASH_ALL, extra),
      );
    });

    it('produces a distinct digest for every output and input type', () => {
      const tx = makeTx();
      const hashTypes = [
        SIGHASH_ALL,
        SIGHASH_NONE,
        SIGHASH_SINGLE,
        SIGHASH_ANYONECANPAY | SIGHASH_ALL,
        SIGHASH_ANYONECANPAY | SIGHASH_NONE,
        SIGHASH_ANYONECANPAY | SIGHASH_SINGLE,
      ];
      const digests = hashTypes.map(hashType => digestOf(tx, 0, hashType));
      expect(new Set(digests).size).toBe(hashTypes.length);
    });

    it('does not commit to the outputs for SIGHASH_NONE', () => {
      const tx = makeTx();
      const changed = makeTx({
        outputs: [{ value: 987654321n, scriptByte: 0xee }],
      });
      for (const hashType of [SIGHASH_NONE, SIGHASH_ANYONECANPAY | SIGHASH_NONE]) {
        expect(digestOf(changed, 0, hashType)).toBe(digestOf(tx, 0, hashType));
      }
      // ...while SIGHASH_ALL does commit to them.
      expect(digestOf(changed, 0, SIGHASH_ALL)).not.toBe(
        digestOf(tx, 0, SIGHASH_ALL),
      );
    });

    it('commits only to the output matching the input index for SIGHASH_SINGLE', () => {
      const tx = makeTx();
      const otherFirstOutputChanged = makeTx({
        outputs: [
          { value: 1n, scriptByte: 0x01 },
          { value: 200000n, scriptByte: 0xa2 },
        ],
      });
      const matchingOutputChanged = makeTx({
        outputs: [
          { value: 100000n, scriptByte: 0xa1 },
          { value: 2n, scriptByte: 0x02 },
        ],
      });
      expect(digestOf(otherFirstOutputChanged, 1, SIGHASH_SINGLE)).toBe(
        digestOf(tx, 1, SIGHASH_SINGLE),
      );
      expect(digestOf(matchingOutputChanged, 1, SIGHASH_SINGLE)).not.toBe(
        digestOf(tx, 1, SIGHASH_SINGLE),
      );
    });

    it('commits to every input unless SIGHASH_ANYONECANPAY is set', () => {
      const tx = makeTx();
      const changed = makeTx({ inputHashes: [0x11, 0x99] });
      const changedScripts = [p2trScript(0xc1), p2trScript(0xff)];
      const changedValues = [50000n, 1n];

      for (const hashType of [
        SIGHASH_ANYONECANPAY | SIGHASH_ALL,
        SIGHASH_ANYONECANPAY | SIGHASH_NONE,
        SIGHASH_ANYONECANPAY | SIGHASH_SINGLE,
      ]) {
        expect(
          digestOf(changed, 0, hashType, {
            prevScripts: changedScripts,
            prevValues: changedValues,
          }),
        ).toBe(digestOf(tx, 0, hashType));
      }

      expect(
        digestOf(changed, 0, SIGHASH_ALL, {
          prevScripts: changedScripts,
          prevValues: changedValues,
        }),
      ).not.toBe(digestOf(tx, 0, SIGHASH_ALL));
    });

    it('commits to the transaction version and lock time', () => {
      const tx = makeTx();
      const otherVersion = makeTx({ version: 3 });
      const otherLocktime = makeTx({ locktime: 500000 });
      const base = digestOf(tx, 0, SIGHASH_ALL);
      expect(digestOf(otherVersion, 0, SIGHASH_ALL)).not.toBe(base);
      expect(digestOf(otherLocktime, 0, SIGHASH_ALL)).not.toBe(base);
    });

    it('commits to the input index', () => {
      const tx = makeTx();
      expect(digestOf(tx, 0, SIGHASH_ALL)).not.toBe(digestOf(tx, 1, SIGHASH_ALL));
    });

    it('accepts the maximum uint32 as input index when the whole transaction is committed to', () => {
      const tx = makeTx();
      const digest = tx.hashForWitnessV1(
        0xffffffff,
        prevScripts(),
        prevValues(),
        SIGHASH_ALL,
      );
      expect(digest).toHaveLength(32);
    });
  });

  describe('BIP342 extensions (leaf hash and annex)', () => {
    it('produces a distinct digest for each of the four spend types', () => {
      const tx = makeTx();
      const combos = [
        {},
        { annex: annex() },
        { leafHash: leafHash() },
        { leafHash: leafHash(), annex: annex() },
      ];
      const digests = combos.map(extra => digestOf(tx, 0, SIGHASH_ALL, extra));
      expect(new Set(digests).size).toBe(4);
      digests.forEach(digest => expect(digest).toHaveLength(64)); // 32 bytes hex
    });

    it('commits to the leaf hash for script path spends', () => {
      const tx = makeTx();
      const withoutLeaf = digestOf(tx, 0, SIGHASH_ALL);
      const withLeaf = digestOf(tx, 0, SIGHASH_ALL, { leafHash: leafHash() });
      expect(withLeaf).not.toBe(withoutLeaf);
    });

    it('commits to the annex', () => {
      const tx = makeTx();
      const withoutAnnex = digestOf(tx, 0, SIGHASH_ALL);
      const withAnnex = digestOf(tx, 0, SIGHASH_ALL, { annex: annex() });
      expect(withAnnex).not.toBe(withoutAnnex);
    });

    it('treats a zero-length annex as present (it changes the spend type)', () => {
      const tx = makeTx();
      expect(
        digestOf(tx, 0, SIGHASH_ALL, { annex: new Uint8Array(0) }),
      ).not.toBe(digestOf(tx, 0, SIGHASH_ALL));
    });

    it('verifies a real tapscript signature from a BIP371 PSBT', () => {
      const tx = Transaction.fromHex(TAPSCRIPT_TX_HEX);
      const prevoutScripts = [fromHex(TAPSCRIPT_PREVOUT_SCRIPT)];
      const prevoutValues = [TAPSCRIPT_PREVOUT_VALUE];

      for (const { pubkey, signature } of TAPSCRIPT_SIGS) {
        const sig = fromHex(signature);
        // 64-byte tapscript signatures imply SIGHASH_DEFAULT.
        const hashType = sig.length === 65 ? sig[64] : SIGHASH_DEFAULT;
        const digest = tx.hashForWitnessV1(
          0,
          prevoutScripts,
          prevoutValues,
          hashType,
          fromHex(TAPSCRIPT_LEAF_HASH),
        );
        expect(toHex(digest)).toBe(TAPSCRIPT_DIGEST);
        expect(
          ecc.verifySchnorr(digest, fromHex(pubkey), sig.slice(0, 64)),
        ).toBe(true);
      }
    });
  });

  describe('observable side effects', () => {
    it('does not mutate the transaction or the supplied prevout arrays', () => {
      const tx = makeTx();
      const before = tx.toHex();
      const scripts = prevScripts();
      const values = prevValues();
      const scriptsBefore = scripts.map(toHex);
      const valuesBefore = values.slice();

      tx.hashForWitnessV1(0, scripts, values, SIGHASH_ALL, leafHash(), annex());

      expect(tx.toHex()).toBe(before);
      expect(scripts.map(toHex)).toEqual(scriptsBefore);
      expect(values).toEqual(valuesBefore);
    });
  });

  describe('validation and error handling', () => {
    it('rejects a values array whose length does not match the input count', () => {
      const tx = makeTx();
      expect(() => tx.hashForWitnessV1(0, prevScripts(), [50000n], SIGHASH_ALL))
        .toThrow('Must supply prevout script and value for all inputs');
      expect(() =>
        tx.hashForWitnessV1(0, prevScripts(), [1n, 2n, 3n], SIGHASH_ALL),
      ).toThrow('Must supply prevout script and value for all inputs');
    });

    it('rejects a prevOutScripts array whose length does not match the input count', () => {
      const tx = makeTx();
      expect(() =>
        tx.hashForWitnessV1(0, [p2trScript(0xc1)], prevValues(), SIGHASH_ALL),
      ).toThrow('Must supply prevout script and value for all inputs');
      expect(() =>
        tx.hashForWitnessV1(
          0,
          [...prevScripts(), p2trScript(0xc3)],
          prevValues(),
          SIGHASH_ALL,
        ),
      ).toThrow('Must supply prevout script and value for all inputs');
    });

    it('requires prevout data for every input even with SIGHASH_ANYONECANPAY', () => {
      const tx = makeTx();
      expect(() =>
        tx.hashForWitnessV1(
          0,
          [p2trScript(0xc1)],
          [50000n],
          SIGHASH_ANYONECANPAY | SIGHASH_ALL,
        ),
      ).toThrow('Must supply prevout script and value for all inputs');
    });

    it('requires outputs for SIGHASH_ALL and SIGHASH_DEFAULT', () => {
      expect(() =>
        makeTxWithoutOutputs().hashForWitnessV1(
          0,
          [p2trScript(0xc1)],
          [50000n],
          SIGHASH_ALL,
        ),
      ).toThrow('Add outputs to the transaction before signing.');
      expect(() =>
        makeTxWithoutOutputs().hashForWitnessV1(
          0,
          [p2trScript(0xc1)],
          [50000n],
          SIGHASH_DEFAULT,
        ),
      ).toThrow('Add outputs to the transaction before signing.');
    });

    it('does not require outputs for SIGHASH_NONE', () => {
      const tx = makeTxWithoutOutputs();
      const digest = tx.hashForWitnessV1(
        0,
        [p2trScript(0xc1)],
        [50000n],
        SIGHASH_NONE,
      );
      expect(digest).toHaveLength(32);
      expect(
        tx.hashForWitnessV1(
          0,
          [p2trScript(0xc1)],
          [50000n],
          SIGHASH_ANYONECANPAY | SIGHASH_NONE,
