      expect(() => p2sh({ hash: new Uint8Array(19) })).toThrow();
      expect(() => p2sh({ hash: new Uint8Array(21) })).toThrow();
    });

    it('rejects an output that is not 23 bytes', () => {
      expect(() => p2sh({ output: new Uint8Array(22) })).toThrow();
      expect(() => p2sh({ output: new Uint8Array(24) })).toThrow();
    });

    it('rejects a non string address', () => {
      expect(() => p2sh({ address: 123 })).toThrow();
    });

    it('rejects non buffer redeem fields', () => {
      expect(() => p2sh({ redeem: { output: 'deadbeef' } })).toThrow();
      expect(() => p2sh({ redeem: { input: 'deadbeef' } })).toThrow();
      expect(() => p2sh({ redeem: { witness: 'deadbeef' } })).toThrow();
