import { p2tr } from './src/esm/payments/p2tr.js';
import { initEccLib } from './src/esm/ecc_lib.js';
import * as ecc from 'tiny-secp256k1';
import * as tools from 'uint8array-tools';
initEccLib(ecc);
const H=h=>tools.fromHex(h); const hex=u=>u?tools.toHex(u):String(u);
const internal=H('79be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798');
const scriptA=H('51');
const cbA=H('c179be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798c276fef1386890619b80e10a4a328572d97493add269df1a15a7f89f8ae8ec09');
function show(label, fn){ try { const o=fn(); console.log(label, 'OK', hex(o.output)); } catch(e){ console.log(label,'ERR',e.constructor.name, JSON.stringify(e.message)); } }
// bad control block length 34
show('cb length 34',()=>p2tr({witness:[scriptA,H('c1'+'00'.repeat(33))]}));
// m > 128
const bigCb = tools.concat([Uint8Array.from([0xc1]), internal, new Uint8Array(32*129)]);
show('m 129',()=>p2tr({witness:[scriptA,bigCb]}));
// parity flip
const cbBad = Uint8Array.from(cbA); cbBad[0] ^= 1;
show('bad parity',()=>p2tr({witness:[scriptA,cbBad]}));
// invalid internal witness zeros
show('invalid internal witness',()=>p2tr({witness:[scriptA,H('c1'+'00'.repeat(32))]}));
// witness non-buffer schema
show('schema witness',()=>p2tr({witness:['51','abc']}));
// scriptTree invalid
show('schema scriptTree',()=>p2tr({internalPubkey:internal, scriptTree:{notoutput:H('51')}}));
// redeemVersion string
show('schema redeemVersion',()=>p2tr({internalPubkey:internal, redeemVersion:'c0'}));
// input 0 len
show('input',()=>p2tr({internalPubkey:internal, input:new Uint8Array(0)}));
EOF"}

