describe('p2tr witness parsing', () => {
  test('derives all fields from a script-path witness', () => {
    const o = p2tr({ witness: [SCRIPT_A, CONTROL_BLOCK_A] });
    expect(hex(o.hash)).toBe(hex(ROOT_AB));
    expect(hex(o.internalPubkey)).toBe(hex(INTERNAL_PUBKEY));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_AB));
    expect(hex(o.output)).toBe(hex(OUTPUT_AB));
    expect(o.address).toBe(ADDRESS_AB);
    expect(hex(o.redeem.output)).toBe(hex(SCRIPT_A));
    expect(o.redeem.witness).toEqual([]);
    expect(o.redeem.redeemVersion).toBe(0xc0);
    expect(o.signature).toBeUndefined();
  });

  test('parses the redeem leaf from a control block for the other leaf', () => {
    const o = p2tr({ witness: [SCRIPT_B, CONTROL_BLOCK_B] });
    expect(hex(o.hash)).toBe(hex(ROOT_AB));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_AB));
    expect(hex(o.redeem.output)).toBe(hex(SCRIPT_B));
    expect(o.redeem.redeemVersion).toBe(0xc0);
  });

  test('separates redeem stack items from the script-path witness', () => {
    const o = p2tr({
      witness: [STACK_ITEM_A, STACK_ITEM_B, SCRIPT_A, CONTROL_BLOCK_A],
    });
    expect(hex(o.redeem.output)).toBe(hex(SCRIPT_A));
    expect(hexes(o.redeem.witness)).toEqual([
      hex(STACK_ITEM_A),
      hex(STACK_ITEM_B),
    ]);
  });

  test('ignores a trailing annex when parsing a script-path witness', () => {
    const o = p2tr({
      witness: [STACK_ITEM_A, SCRIPT_A, CONTROL_BLOCK_A, ANNEX],
    });
    expect(hex(o.hash)).toBe(hex(ROOT_AB));
    expect(hex(o.redeem.output)).toBe(hex(SCRIPT_A));
    expect(hexes(o.redeem.witness)).toEqual([hex(STACK_ITEM_A)]);
    expect(hexes(o.witness)).toEqual([
      hex(STACK_ITEM_A),
      hex(SCRIPT_A),
      hex(CONTROL_BLOCK_A),
      hex(ANNEX),
    ]);
  });

  test('derives a signature from a key-path witness when a pubkey is present', () => {
    const o = p2tr({ pubkey: TWEAKED_AB, witness: [SIGNATURE] });
    expect(hex(o.signature)).toBe(hex(SIGNATURE));
    expect(hexes(o.witness)).toEqual([hex(SIGNATURE)]);
    expect(o.hash).toBeNull();
  });

  test('accepts a matching explicit signature for a key-path witness', () => {
    const o = p2tr({
      pubkey: TWEAKED_AB,
      witness: [SIGNATURE],
      signature: SIGNATURE,
    });
    expect(hex(o.signature)).toBe(hex(SIGNATURE));
  });

  test('accepts matching redeem data against a script-path witness', () => {
    const o = p2tr({
      witness: [STACK_ITEM_A, STACK_ITEM_B, SCRIPT_A, CONTROL_BLOCK_A],
      redeem: {
        output: SCRIPT_A,
        witness: [STACK_ITEM_A, STACK_ITEM_B],
        redeemVersion: 0xc0,
      },
    });
    expect(hex(o.redeem.output)).toBe(hex(SCRIPT_A));
    expect(hexes(o.redeem.witness)).toEqual([
      hex(STACK_ITEM_A),
      hex(STACK_ITEM_B),
    ]);
  });
});

