  test('prefers the top-level redeemVersion', () => {
    const o = p2tr({
      internalPubkey: INTERNAL_PUBKEY,
      redeemVersion: 0xc2,
      redeem: { redeemVersion: 0xc4 },
    });
    expect(o.redeemVersion).toBe(0xc2);
  });

  test('treats a falsy top-level redeemVersion as absent', () => {
    const o = p2tr({ internalPubkey: INTERNAL_PUBKEY, redeemVersion: 0 });
    expect(o.redeemVersion).toBe(0xc0);
  });

  test('honours a zero redeem.redeemVersion', () => {
    const o = p2tr({
      internalPubkey: INTERNAL_PUBKEY,
      redeem: { redeemVersion: 0 },
