describe('p2tr data requirements', () => {
  test('throws when no usable data is supplied', () => {
    expect(() => p2tr({})).toThrow(new TypeError('Not enough data'));
  });

  test('throws when witness is an empty array', () => {
    expect(() => p2tr({ witness: [] })).toThrow('Not enough data');
  });

  test('throws when witness contains a single element', () => {
    expect(() => p2tr({ witness: [SIGNATURE] })).toThrow('Not enough data');
  });

  test('throws when only a signature is supplied', () => {
    expect(() => p2tr({ signature: SIGNATURE })).toThrow('Not enough data');
  });

  test('accepts a witness with an annex and derives the signature', () => {
    const o = p2tr({ witness: [SIGNATURE, ANNEX] });
    expect(hex(o.signature)).toBe(hex(SIGNATURE));
    expect(o.hash).toBeNull();
    expect(hexes(o.witness)).toEqual([hex(SIGNATURE), hex(ANNEX)]);
  });
});

describe('p2tr derivation from address', () => {
  test('derives pubkey, output and address metadata', () => {
    const o = p2tr({ address: ADDRESS_NO_HASH });
    expect(o.name).toBe('p2tr');
    expect(o.network).toBe(bitcoin);
    expect(o.address).toBe(ADDRESS_NO_HASH);
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_NO_HASH));
    expect(hex(o.output)).toBe(hex(OUTPUT_NO_HASH));
    expect(o.hash).toBeNull();
  });

  test('derives a testnet address given a testnet network', () => {
    const o = p2tr({ address: ADDRESS_NO_HASH_TESTNET, network: testnet });
    expect(o.network).toBe(testnet);
    expect(o.address).toBe(ADDRESS_NO_HASH_TESTNET);
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_NO_HASH));
    expect(hex(o.output)).toBe(hex(OUTPUT_NO_HASH));
  });

  test('accepts an address and a matching pubkey', () => {
    const o = p2tr({ address: ADDRESS_NO_HASH, pubkey: TWEAKED_NO_HASH });
    expect(o.address).toBe(ADDRESS_NO_HASH);
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_NO_HASH));
  });

  test('rejects a pubkey that does not match the address', () => {
    expect(() =>
      p2tr({ address: ADDRESS_NO_HASH, pubkey: OTHER_PUBKEY }),
    ).toThrow('Pubkey mismatch');
  });
});

describe('p2tr derivation from output', () => {
  test('derives pubkey and address from an output script', () => {
    const o = p2tr({ output: OUTPUT_NO_HASH });
    expect(hex(o.output)).toBe(hex(OUTPUT_NO_HASH));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_NO_HASH));
    expect(o.address).toBe(ADDRESS_NO_HASH);
    expect(o.hash).toBeNull();
  });

  test('accepts an output and a matching pubkey', () => {
    const o = p2tr({ output: OUTPUT_AB, pubkey: TWEAKED_AB });
    expect(hex(o.output)).toBe(hex(OUTPUT_AB));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_AB));
  });

  test('derives a testnet address from an output', () => {
    const o = p2tr({ output: OUTPUT_NO_HASH, network: testnet });
    expect(o.address).toBe(ADDRESS_NO_HASH_TESTNET);
  });
});

describe('p2tr derivation from pubkey', () => {
  test('derives address and output from a tweaked pubkey', () => {
    const o = p2tr({ pubkey: TWEAKED_NO_HASH });
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_NO_HASH));
    expect(hex(o.output)).toBe(hex(OUTPUT_NO_HASH));
    expect(o.address).toBe(ADDRESS_NO_HASH);
    expect(o.internalPubkey).toBeUndefined();
    expect(o.hash).toBeNull();
    expect(o.redeemVersion).toBe(0xc0);
  });
});

describe('p2tr derivation from internalPubkey', () => {
  test('tweaks an internal pubkey without a merkle root', () => {
    const o = p2tr({ internalPubkey: INTERNAL_PUBKEY });
    expect(hex(o.internalPubkey)).toBe(hex(INTERNAL_PUBKEY));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_NO_HASH));
    expect(hex(o.output)).toBe(hex(OUTPUT_NO_HASH));
    expect(o.address).toBe(ADDRESS_NO_HASH);
    expect(o.hash).toBeNull();
  });

  test('tweaks an internal pubkey with a merkle root', () => {
    const o = p2tr({ internalPubkey: INTERNAL_PUBKEY, hash: MERKLE_ROOT });
    expect(hex(o.hash)).toBe(hex(MERKLE_ROOT));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_WITH_HASH));
    expect(hex(o.output)).toBe(hex(OUTPUT_WITH_HASH));
    expect(o.address).toBe(ADDRESS_WITH_HASH);
  });

  test('respects a testnet network when deriving the address', () => {
    const o = p2tr({ internalPubkey: INTERNAL_PUBKEY, network: testnet });
    expect(o.network).toBe(testnet);
    expect(o.address).toBe(ADDRESS_NO_HASH_TESTNET);
    expect(hex(o.output)).toBe(hex(OUTPUT_NO_HASH));
  });

  test('defaults to the bitcoin network', () => {
    const o = p2tr({ internalPubkey: INTERNAL_PUBKEY });
    expect(o.name).toBe('p2tr');
    expect(o.network).toBe(bitcoin);
  });
});

describe('p2tr scriptTree handling', () => {
  test('computes the merkle root and tweaked key for a single leaf', () => {
    const o = p2tr({
      internalPubkey: INTERNAL_PUBKEY,
      scriptTree: { output: SCRIPT_A },
    });
    expect(hex(o.hash)).toBe(hex(LEAF_HASH_A));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_SINGLE_LEAF));
    expect(hex(o.output)).toBe(hex(OUTPUT_SINGLE_LEAF));
    expect(o.address).toBe(ADDRESS_SINGLE_LEAF);
  });

  test('computes the merkle root for a two-leaf tree', () => {
    const o = p2tr({
      internalPubkey: INTERNAL_PUBKEY,
      scriptTree: [{ output: SCRIPT_A }, { output: SCRIPT_B }],
    });
    expect(hex(o.hash)).toBe(hex(ROOT_AB));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_AB));
    expect(hex(o.output)).toBe(hex(OUTPUT_AB));
    expect(o.address).toBe(ADDRESS_AB);
  });

  test('accepts an explicit hash matching the scriptTree root', () => {
    const o = p2tr({
      internalPubkey: INTERNAL_PUBKEY,
      hash: ROOT_AB,
      scriptTree: [{ output: SCRIPT_A }, { output: SCRIPT_B }],
    });
    expect(hex(o.hash)).toBe(hex(ROOT_AB));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_AB));
  });

  test('constructs a script-path witness for a single-leaf tree', () => {
    const o = p2tr({
      internalPubkey: INTERNAL_PUBKEY,
      scriptTree: { output: SCRIPT_A },
      redeem: { output: SCRIPT_A },
    });
    expect(hexes(o.witness)).toEqual([
      hex(SCRIPT_A),
      hex(CONTROL_BLOCK_SINGLE),
    ]);
    expect(hex(o.hash)).toBe(hex(LEAF_HASH_A));
  });

  test('constructs a script-path witness with the sibling path for a tree', () => {
    const o = p2tr({
      internalPubkey: INTERNAL_PUBKEY,
      scriptTree: [{ output: SCRIPT_A }, { output: SCRIPT_B }],
      redeem: { output: SCRIPT_A },
    });
    expect(hexes(o.witness)).toEqual([hex(SCRIPT_A), hex(CONTROL_BLOCK_A)]);
    expect(hex(o.hash)).toBe(hex(ROOT_AB));
  });

  test('rejects a scriptTree that is not a valid tap tree', () => {
    expect(() =>
      p2tr({
        internalPubkey: INTERNAL_PUBKEY,
        scriptTree: { notAnOutput: SCRIPT_A },
      }),
    ).toThrow('Taptree is not of type isTaptree');
  });

  test('rejects a redeem script that is not present in the tree', () => {
    expect(() =>
      p2tr({
        internalPubkey: INTERNAL_PUBKEY,
        scriptTree: { output: SCRIPT_A },
        redeem: { output: SCRIPT_B },
      }),
    ).toThrow('Redeem script not in tree');
  });
});

describe('p2tr redeemVersion resolution', () => {
  test('defaults to LEAF_VERSION_TAPSCRIPT', () => {
    expect(p2tr({ internalPubkey: INTERNAL_PUBKEY }).redeemVersion).toBe(0xc0);
  });

  test('uses an explicit redeemVersion', () => {
    const o = p2tr({ internalPubkey: INTERNAL_PUBKEY, redeemVersion: 0xc2 });
    expect(o.redeemVersion).toBe(0xc2);
  });

  test('falls back to redeem.redeemVersion', () => {
    const o = p2tr({
      internalPubkey: INTERNAL_PUBKEY,
      redeem: { redeemVersion: 0xc2 },
    });
    expect(o.redeemVersion).toBe(0xc2);
  });

  test('prefers the top-level redeemVersion', () => {
    const o = p2tr({
      internalPubkey: INTERNAL_PUBKEY,
      redeemVersion: 0xc2,
      redeem: { redeemVersion: 0xc4 },
    });
    expect(o.redeemVersion).toBe(0xc2);
  });

  test('treats a falsy top-level redeemVersion as absent', () => {
    const o = p2tr({ internalPubkey: INTERNAL_PUBKEY, redeemVersion: 0 });
    expect(o.redeemVersion).toBe(0xc0);
  });

  test('honours a zero redeem.redeemVersion', () => {
    const o = p2tr({
      internalPubkey: INTERNAL_PUBKEY,
      redeem: { redeemVersion: 0 },
    });
    expect(o.redeemVersion).toBe(0);
  });
});

describe('p2tr witness parsing', () => {
  test('derives all fields from a script-path witness', () => {
    const o = p2tr({ witness: [SCRIPT_A, CONTROL_BLOCK_A] });
    expect(hex(o.hash)).toBe(hex(ROOT_AB));
    expect(hex(o.internalPubkey)).toBe(hex(INTERNAL_PUBKEY));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_AB));
    expect(hex(o.output)).toBe(hex(OUTPUT_AB));
    expect(o.address).toBe(ADDRESS_AB);
    expect(hex(o.redeem.output)).toBe(hex(SCRIPT_A));
    expect(o.redeem.witness).toEqual([]);
    expect(o.redeem.redeemVersion).toBe(0xc0);
    expect(o.signature).toBeUndefined();
  });

  test('parses the redeem leaf from a control block for the other leaf', () => {
    const o = p2tr({ witness: [SCRIPT_B, CONTROL_BLOCK_B] });
    expect(hex(o.hash)).toBe(hex(ROOT_AB));
    expect(hex(o.pubkey)).toBe(hex(TWEAKED_AB));
    expect(hex(o.redeem.output)).toBe(hex(SCRIPT_B));
    expect(o.redeem.redeemVersion).toBe(0xc0);
  });

  test('separates redeem stack items from the script-path witness', () => {
    const o = p2tr({
      witness: [STACK_ITEM_A, STACK_ITEM_B, SCRIPT_A, CONTROL_BLOCK_A],
    });
    expect(hex(o.redeem.output)).toBe(hex(SCRIPT_A));
    expect(hexes(o.redeem.witness)).toEqual([
      hex(STACK_ITEM_A),
      hex(STACK_ITEM_B),
    ]);
  });

  test('ignores a trailing annex when parsing a script-path witness', () => {
    const o = p2tr({
      witness: [STACK_ITEM_A, SCRIPT_A, CONTROL_BLOCK_A, ANNEX],
    });
    expect(hex(o.hash)).toBe(hex(ROOT_AB));
    expect(hex(o.redeem.output)).toBe(hex(SCRIPT_A));
    expect(hexes(o.redeem.witness)).toEqual([hex(STACK_ITEM_A)]);
    expect(hexes(o.witness)).toEqual([
      hex(STACK_ITEM_A),
      hex(SCRIPT_A),
      hex(CONTROL_BLOCK_A),
      hex(ANNEX),
    ]);
  });

  test('derives a signature from a key-path witness when a pubkey is present', () => {
    const o = p2tr({ pubkey: TWEAKED_AB, witness: [SIGNATURE] });
    expect(hex(o.signature)).toBe(hex(SIGNATURE));
    expect(hexes(o.witness)).toEqual([hex(SIGNATURE)]);
    expect(o.hash).toBeNull();
  });

  test('accepts a matching explicit signature for a key-path witness', () => {
    const o = p2tr({
      pubkey: TWEAKED_AB,
      witness: [SIGNATURE],
      signature: SIGNATURE,
    });
    expect(hex(o.signature)).toBe(hex(SIGNATURE));
  });

  test('accepts matching redeem data against a script-path witness', () => {
    const o = p2tr({
      witness: [STACK_ITEM_A, STACK_ITEM_B, SCRIPT_A, CONTROL_BLOCK_A],
      redeem: {
        output: SCRIPT_A,
        witness: [STACK_ITEM_A, STACK_ITEM_B],
        redeemVersion: 0xc0,
      },
    });
    expect(hex(o.redeem.output)).toBe(hex(SCRIPT_A));
    expect(hexes(o.redeem.witness)).toEqual([
      hex(STACK_ITEM_A),
      hex(STACK_ITEM_B),
    ]);
  });
});

