    expect(hex(o.pubkey)).toBe('11'.repeat(32));
    expect(o.address).toMatch(/^bc1p/);
  });

  test('does not mutate the input data object or options', () => {
    const data = { internalPubkey: INTERNAL_PUBKEY };
    const opts = {};
    p2tr(data, opts);
    expect(Object.keys(data)).toEqual(['internalPubkey']);
    expect(opts).toEqual({});
  });
});
