const ADDRESS =
  'bc1qqqqsyqcyq5rqwzqfpg9scrgwpugpzysnzs23v9ccrydpk8qarc0szrtjt7';
const TESTNET_ADDRESS =
  'tb1qqqqsyqcyq5rqwzqfpg9scrgwpugpzysnzs23v9ccrydpk8qarc0s4taa33';
const ZERO_HASH = new Uint8Array(32);
const ZERO_HASH_ADDRESS =
  'bc1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqthqst8';
const OTHER_HASH = new Uint8Array(32).fill(0xff);
const OTHER_OUTPUT = fromHex(`0020${'ff'.repeat(32)}`);

