function expectTypeError(fn, message) {
  expect(fn).toThrow(TypeError);
  expect(fn).toThrow(message);
}

describe('p2wsh', () => {
  describe('construction from a hash', () => {
    it('derives a mainnet address and output from a 32-byte hash', () => {
      const payment = p2wsh({ hash: HASH });

      expect(payment.network).toBe(bitcoin);
      expect(payment.hash).toEqual(HASH);
      expect(payment.output).toEqual(OUTPUT);
      expect(payment.address).toBe(ADDRESS);
      expect(payment.input).toBeUndefined();
      expect(payment.redeem).toBeUndefined();
