  '4ae81572f06e1b88fd5ced7a1a000945432e83e1551e6f721ee9c00b8cc33260';
const REDEEM_OUTPUT_HEX = `0020${REDEEM_HASH_HEX}`;
const REDEEM_ADDRESS =
  'bc1qft5p2uhsdcdc3l2ua4ap5qqfg4pjaqlp250x7us7a8qqhrxrxfsq2gp3gp';
const REDEEM_TESTNET_ADDRESS =
  'tb1qft5p2uhsdcdc3l2ua4ap5qqfg4pjaqlp250x7us7a8qqhrxrxfsqaqh7jw';

const DATA_A = fromHex('aa');
const DATA_B = fromHex('bb');

// A valid, uncompressed secp256k1 generator-point public key.
const UNCOMPRESSED_PUBKEY = fromHex(
  '0479be667ef9dcbbac55a06295ce870b07029bfcdb2dce28d959f2815b16f81798' +
    '483ada7726a3c4655da4fbfc0e1108a8fd17b448a68554199c47d08ffb10d4b8',
);
const UNCOMPRESSED_PUBKEY_SCRIPT = bscript.compile([UNCOMPRESSED_PUBKEY]);

function expectTypeError(fn, message) {
  expect(fn).toThrow(TypeError);
  expect(fn).toThrow(message);
}

describe('p2wsh', () => {
  describe('construction from a hash', () => {
    it('derives a mainnet address and output from a 32-byte hash', () => {
      const payment = p2wsh({ hash: HASH });

      expect(payment.network).toBe(bitcoin);
      expect(payment.hash).toEqual(HASH);
      expect(payment.output).toEqual(OUTPUT);
      expect(payment.address).toBe(ADDRESS);
      expect(payment.input).toBeUndefined();
      expect(payment.redeem).toBeUndefined();
      expect(payment.witness).toBeUndefined();
      expect(payment.name).toBe('p2wsh');
    });

    it('accepts an all-zero hash', () => {
      const payment = p2wsh({ hash: ZERO_HASH });

      expect(payment.hash).toEqual(ZERO_HASH);
      expect(payment.output).toEqual(fromHex(`0020${'00'.repeat(32)}`));
      expect(payment.address).toBe(ZERO_HASH_ADDRESS);
    });

    it('derives the address with a custom network', () => {
      const payment = p2wsh({ hash: HASH, network: testnet });

      expect(payment.network).toBe(testnet);
      expect(payment.address).toBe(TESTNET_ADDRESS);
      expect(payment.output).toEqual(OUTPUT);
    });
  });

  describe('construction from an output or address', () => {
    it('derives the hash and address from a P2WSH output', () => {
      const payment = p2wsh({ output: OUTPUT });

      expect(payment.output).toEqual(OUTPUT);
      expect(payment.hash).toEqual(HASH);
      expect(payment.address).toBe(ADDRESS);
      expect(payment.name).toBe('p2wsh');
    });

    it('derives the hash and output from a BIP173 P2WSH address', () => {
      const payment = p2wsh({ address: BIP173_ADDRESS });

      expect(payment.address).toBe(BIP173_ADDRESS);
      expect(toHex(payment.hash)).toBe(BIP173_HASH_HEX);
      expect(toHex(payment.output)).toBe(BIP173_OUTPUT_HEX);
    });

    it('uses the redeem network when no top-level network is provided', () => {
      const payment = p2wsh({
        redeem: { network: testnet, output: REDEEM_SCRIPT },
      });

      expect(payment.network).toBe(testnet);
      expect(toHex(payment.hash)).toBe(REDEEM_HASH_HEX);
      expect(toHex(payment.output)).toBe(REDEEM_OUTPUT_HEX);
      expect(payment.address).toBe(REDEEM_TESTNET_ADDRESS);
    });
  });

  describe('redeem and witness derivation', () => {
    it('derives a P2WSH hash from redeem.output', () => {
      const payment = p2wsh({ redeem: { output: REDEEM_SCRIPT } });

      expect(payment.redeem).toEqual({ output: REDEEM_SCRIPT });
      expect(toHex(payment.hash)).toBe(REDEEM_HASH_HEX);
      expect(toHex(payment.output)).toBe(REDEEM_OUTPUT_HEX);
      expect(payment.address).toBe(REDEEM_ADDRESS);
      expect(payment.input).toBeUndefined();
      expect(payment.witness).toBeUndefined();
      expect(payment.name).toBe('p2wsh');
    });

    it('builds a witness stack from redeem.witness and redeem.output', () => {
      const payment = p2wsh({
        redeem: { output: REDEEM_SCRIPT, witness: [DATA_A, DATA_B] },
      });

      expect(payment.witness.map(toHex)).toEqual(['aa', 'bb', '51']);
      expect(payment.redeem.witness.map(toHex)).toEqual(['aa', 'bb']);
      expect(payment.redeem.output).toEqual(REDEEM_SCRIPT);
      expect(payment.input).toEqual(EMPTY);
      expect(toHex(payment.hash)).toBe(REDEEM_HASH_HEX);
    });

    it('converts a push-only redeem.input into a witness stack', () => {
      const redeem = {
        input: bscript.compile([bscript.OPS.OP_1, bscript.OPS.OP_2]),
        output: REDEEM_SCRIPT,
      };
      const payment = p2wsh({ redeem });

      expect(payment.witness.map(toHex)).toEqual(['01', '02', '51']);
      expect(payment.input).toEqual(EMPTY);
      expect(payment.redeem.input).toEqual(EMPTY);
      expect(payment.redeem.witness.map(toHex)).toEqual(['01', '02']);
      expect(payment.redeem.output).toEqual(REDEEM_SCRIPT);
      // The caller's redeem object is not mutated.
      expect(toHex(redeem.input)).toBe('5152');
    });

    it('derives redeem details and an empty input from a witness stack', () => {
      const witness = [DATA_A, DATA_B, REDEEM_SCRIPT];
      const payment = p2wsh({ witness });

      expect(payment.witness).toBe(witness);
      expect(payment.input).toEqual(EMPTY);
      expect(payment.redeem.output).toEqual(REDEEM_SCRIPT);
      expect(payment.redeem.input).toEqual(EMPTY);
      expect(payment.redeem.witness.map(toHex)).toEqual(['aa', 'bb']);
      expect(toHex(payment.hash)).toBe(REDEEM_HASH_HEX);
      expect(payment.address).toBe(REDEEM_ADDRESS);
    });

    it('includes a redeem name in the payment name', () => {
      const payment = p2wsh({
        redeem: { output: REDEEM_SCRIPT, name: 'multisig' },
      });

      expect(payment.name).toBe('p2wsh-multisig');
    });
  });

  describe('options', () => {
    it('skips extended cross-source validation when validate is false', () => {
      const mismatched = {
        address: BIP173_ADDRESS,
        hash: OTHER_HASH,
      };

      expect(() => p2wsh(mismatched)).toThrow('Hash mismatch');

      const payment = p2wsh(mismatched, { validate: false });
      expect(payment.address).toBe(BIP173_ADDRESS);
      expect(payment.hash).toEqual(OTHER_HASH);
      expect(payment.output).toEqual(OTHER_OUTPUT);
    });

    it('performs extended validation by default', () => {
      expect(() =>
        p2wsh({ address: BIP173_ADDRESS, hash: OTHER_HASH }),
      ).toThrow('Hash mismatch');
    });
  });

  describe('shape and schema validation', () => {
    it('rejects an empty payment object', () => {
      expectTypeError(() => p2wsh({}), 'Not enough data');
    });

    it('validates that hash is exactly 32 bytes', () => {
      expect(() => p2wsh({ hash: new Uint8Array(31) })).toThrow(
        /Expected 32/,
      );
    });

    it('validates that output is exactly 34 bytes', () => {
      expect(() => p2wsh({ hash: HASH, output: new Uint8Array(33) })).toThrow(
        /Expected 34/,
      );
    });

    it('validates the address type', () => {
      expect(() => p2wsh({ hash: HASH, address: 123 })).toThrow(
        /Expected string/,
      );
    });

    it('validates that top-level input is empty', () => {
      expect(() =>
        p2wsh({ hash: HASH, input: new Uint8Array([0x01]) }),
      ).toThrow(/Expected 0/);
    });

    it('validates the witness container type', () => {
      expect(() => p2wsh({ hash: HASH, witness: 'not-an-array' })).toThrow(
        /Expected Array/,
      );
    });

    it('validates redeem.input type', () => {
      expect(() =>
        p2wsh({ hash: HASH, redeem: { input: 'not-a-buffer' } }),
      ).toThrow(/Expected Uint8Array/);
    });
  });

  describe('address and source validation', () => {
    it('rejects an address with a mismatched Bech32 prefix', () => {
      expectTypeError(
        () => p2wsh({ address: TESTNET_ADDRESS }),
        'Invalid prefix or Network mismatch',
      );
    });

    it('rejects a non-zero witness version', () => {
      expectTypeError(
        () =>
          p2wsh({
            address:
              'bc1pqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq5us4ke',
          }),
        'Invalid address version',
      );
    });

    it('rejects an address whose witness program is not 32 bytes', () => {
      expectTypeError(
        () => p2wsh({ address: 'bc1qqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqqq9e75rs' }),
        'Invalid address data',
      );
    });

    it('rejects a hash that mismatches an address', () => {
      expectTypeError(
        () => p2wsh({ address: BIP173_ADDRESS, hash: OTHER_HASH }),
        'Hash mismatch',
      );
    });

    it('rejects a hash that mismatches an output', () => {
      expectTypeError(
        () => p2wsh({ hash: OTHER_HASH, output: OUTPUT }),
        'Hash mismatch',
      );
    });

    it('rejects a hash that mismatches redeem.output', () => {
      expectTypeError(
        () => p2wsh({ hash: OTHER_HASH, redeem: { output: REDEEM_SCRIPT } }),
        'Hash mismatch',
      );
    });

    it('validates the output witness program prefix', () => {
      const invalidOutput = new Uint8Array(34);
      invalidOutput[0] = bscript.OPS.OP_1;
      invalidOutput[1] = 0x20;

      expectTypeError(
        () => p2wsh({ output: invalidOutput }),
        'Output is invalid',
      );
    });

    it('validates the output witness program length byte', () => {
      const invalidOutput = new Uint8Array(34);
      invalidOutput[0] = bscript.OPS.OP_0;
      invalidOutput[1] = 0x21;

      expectTypeError(
        () => p2wsh({ output: invalidOutput }),
        'Output is invalid',
      );
    });
  });

  describe('redeem validation', () => {
    it('rejects a redeem network different from the top-level network', () => {
      expectTypeError(
        () =>
          p2wsh({
            network: bitcoin,
            redeem: { network: testnet, output: REDEEM_SCRIPT },
          }),
        'Network mismatch',
      );
    });

    it('rejects simultaneous redeem.input and redeem.witness', () => {
      expectTypeError(
        () =>
          p2wsh({
            redeem: {
              input: REDEEM_SCRIPT,
              output: REDEEM_SCRIPT,
              witness: [DATA_A],
            },
          }),
        'Ambiguous witness source',
      );
    });

    it('rejects an empty redeem.output', () => {
      expectTypeError(
        () => p2wsh({ redeem: { output: EMPTY } }),
        'Redeem.output is invalid',
      );
    });

    it('rejects an undecompilable redeem.output', () => {
      expectTypeError(
        () => p2wsh({ redeem: { output: Uint8Array.from([0x4c]) } }),
        'Redeem.output is invalid',
      );
    });

    it('accepts a redeem.output of exactly 3600 bytes', () => {
      const atLimit = bscript.compile([new Uint8Array(3597)]);
      expect(atLimit.byteLength).toBe(3600);

      const payment = p2wsh({ redeem: { output: atLimit } });
      expect(toHex(payment.hash)).toBe(
        '5d6bb5aa0e0f7113efa75ba84636f385e8f2904825758b747697b891543ca698',
      );
    });

    it('rejects a redeem.output larger than 3600 bytes', () => {
      const tooLarge = bscript.compile([new Uint8Array(3601)]);
      expect(tooLarge.byteLength).toBeGreaterThan(3600);

      expectTypeError(
        () => p2wsh({ redeem: { output: tooLarge } }),
        'Redeem.output unspendable if larger than 3600 bytes',
      );
    });

    it('accepts a redeem.output with exactly 201 non-push operations', () => {
      const atLimit = bscript.compile(
        new Array(201).fill(bscript.OPS.OP_ADD),
      );

      const payment = p2wsh({ redeem: { output: atLimit } });
      expect(toHex(payment.hash)).toBe(
        '2c42d9056262dede4b9cece906a650dea81ec4a6365bc6c2d725f6cbde685a1c',
      );
    });

    it('rejects a redeem.output with more than 201 non-push operations', () => {
      const tooMany = bscript.compile(
        new Array(202).fill(bscript.OPS.OP_ADD),
      );

      expectTypeError(
        () => p2wsh({ redeem: { output: tooMany } }),
        'Redeem.output unspendable with more than 201 non-push ops',
      );
    });

    it('rejects a non-push-only redeem.input', () => {
      expectTypeError(
        () =>
          p2wsh({
            redeem: { input: bscript.compile([bscript.OPS.OP_ADD]) },
          }),
        'Non push-only scriptSig',
      );
    });

    it('rejects witness and redeem.witness disagreement', () => {
      expectTypeError(
        () =>
          p2wsh({
            witness: [DATA_B],
            redeem: { witness: [DATA_A] },
          }),
        'Witness and redeem.witness mismatch',
      );
    });

    it('rejects witness and redeem.output disagreement', () => {
      expectTypeError(
        () =>
          p2wsh({
            witness: [bscript.compile([bscript.OPS.OP_2])],
            redeem: { output: REDEEM_SCRIPT },
          }),
        'Witness and redeem.output mismatch',
      );
    });

    it('rejects an uncompressed pubkey in redeem.input', () => {
      expectTypeError(
        () =>
          p2wsh({
            redeem: {
              input: bscript.compile([UNCOMPRESSED_PUBKEY]),
            },
          }),
        'redeem.input or redeem.output contains uncompressed pubkey',
      );
    });

    it('rejects an uncompressed pubkey in redeem.output', () => {
      expectTypeError(
        () => p2wsh({ redeem: { output: UNCOMPRESSED_PUBKEY_SCRIPT } }),
        'redeem.input or redeem.output contains uncompressed pubkey',
      );
    });

    it('rejects an uncompressed pubkey directly in the witness', () => {
      expectTypeError(
        () => p2wsh({ witness: [UNCOMPRESSED_PUBKEY] }),
        'Witness contains uncompressed pubkey',
      );
    });

    it('rejects an uncompressed pubkey inside the witness script', () => {
      expectTypeError(
        () => p2wsh({ witness: [UNCOMPRESSED_PUBKEY_SCRIPT] }),
        'Witness contains uncompressed pubkey',
      );
    });
  });
});

