      expect(tx.toHex()).toBe(txBefore);
      expect(prevOutScripts.map(script => tools.toHex(script))).toEqual(
        PREVOUT_SCRIPTS.map(script => tools.toHex(script)),
      );
      expect(values).toEqual(VALUES);
    });
  });
