import { describe, expect, test } from '@jest/globals';
import { readFileSync } from 'node:fs';
import { Transaction } from '../../../src/esm/transaction.js';
import * as tools from 'uint8array-tools';

const fixture = JSON.parse(
  readFileSync(new URL('../../fixtures/transaction.json', import.meta.url), 'utf8'),
);

// A P2TR scriptPubKey is OP_1 (0x51), a 32-byte push (0x20), and a 32-byte key.
const PREVOUT_SCRIPTS = [
  tools.fromHex('5120' + '33'.repeat(32)),
  tools.fromHex('5120' + '44'.repeat(32)),
];
const VALUES = [50000n, 60000n];
const LEAF_HASH = tools.fromHex('aa'.repeat(32));
const ANNEX = tools.fromHex('50');

function buildTransaction() {
  const tx = new Transaction();
  tx.version = 2;
  tx.locktime = 0;
  tx.addInput(tools.fromHex('11'.repeat(32)), 0, 0xfffffffe);
  tx.addInput(tools.fromHex('22'.repeat(32)), 1, 0xfffffffd);
  tx.addOutput(tools.fromHex('51'), 1000n);
  tx.addOutput(tools.fromHex('52'), 2000n);
  return tx;
}

function sighash(tx, hashType = Transaction.SIGHASH_DEFAULT, options = {}) {
  const {
    inIndex = 0,
    prevOutScripts = PREVOUT_SCRIPTS,
    values = VALUES,
    leafHash = undefined,
    annex = undefined,
  } = options;
  return tx.hashForWitnessV1(
    inIndex,
    prevOutScripts,
    values,
    hashType,
    leafHash,
    annex,
  );
}

// Expected values below are derived from the BIP341/BIP342 signature message
// specification, independently of this implementation.
const HASH_TYPE_VECTORS = [
  [0x00, '98b051e0013495e5005381704d9a3c26cf96ab2b95127d2c7e2061a34ffde468'],
  [0x01, '9ed1ff8f5edaa3c541ff36dbc34a24aeaffb1732cb7226fbaae2ca044643663a'],
  [0x02, '0d9e56422b1962719ed78e7e779cd766586ab544d0c1c2177d2a227482335b58'],
  [0x03, '7641e958f999ceceae0141872974a91c3c0dc2dc35a19a8e9009f615ca0648a2'],
  [0x80, 'c4972023db023df0cb62fd30f56a7442145fa7a0670f8cf355e9a8b4f59dc7af'],
  [0x81, '38528ba6447752cb41375e4fb82a0b97d9ea15b64b20d7237987ef032365988a'],
  [0x82, '221cf300b59d60a1075c34b213fcc2ee20aa577d6847317ca0f0243105970676'],
  [0x83, '2b88ed43cef1ee002899230a831080ce0a377511574c794b70707832039bd71d'],
];

const EXTENSION_VECTORS = [
  [
    'leafHash only',
    { hashType: 0x00, leafHash: LEAF_HASH },
    '943c0d97e478337d71b6dbee92737d0e5a3be270c3c5ff2c32311c4d5ea4a9ad',
  ],
  [
    'annex only',
    { hashType: 0x00, annex: ANNEX },
    '1e768375f3521c95f44b64b406be4a57acd3dc002623cf97183da98cb69c0ffa',
  ],
  [
    'leafHash and annex',
    { hashType: 0x00, leafHash: LEAF_HASH, annex: ANNEX },
    '12a5907428830a9881511c9e8ab9dce0e88c884d8087c820abb465e4f924f9d8',
  ],
  [
    'ANYONECANPAY with leafHash only',
    { hashType: 0x81, leafHash: LEAF_HASH },
    'd79f4558ab70cdffbff66525c5f18a90dea7c4e298ea8a0966e47f31a73f1526',
  ],
  [
    'ANYONECANPAY with annex only',
    { hashType: 0x81, annex: ANNEX },
    '608ecd1d0debdce193aa593d06f395d7d928fbbac54995912d71865a847ce193',
  ],
  [
    'ANYONECANPAY with leafHash and annex',
    { hashType: 0x81, leafHash: LEAF_HASH, annex: ANNEX },
    '9b8db6849faace7dfed68f0d8338294434430622e41a5c3d9a919b2125f933af',
  ],
];

describe('Transaction.hashForWitnessV1', () => {
  describe('external BIP341 reference vectors', () => {
    const taprootVector = fixture.taprootSigning[0];

    test.each(
      taprootVector.cases.map(tc => [
        tc.vin,
        tc.typeHex,
        parseInt(tc.typeHex, 16),
        tc.hash,
      ]),
    )(
      'matches the published sighash for input %i with hash type 0x%s',
      (vin, _typeHex, hashType, expectedHash) => {
        const tx = Transaction.fromHex(taprootVector.txHex);
        const prevOutScripts = taprootVector.utxos.map(utxo =>
          tools.fromHex(utxo.scriptHex),
        );
